-- ═══════════════════════════════════════════════════════════════
-- OC Agent — AI coding assistant for OpenComputers (GTNH)
-- Single-file build (generated by scripts/build_single.lua).
-- All agent.* modules are embedded as package.preload entries; the
-- entry body is src/agent/init.lua inlined verbatim at the end.
-- ═══════════════════════════════════════════════════════════════

-- Make the sibling src/agent/ tree require-able (no-op for the
-- preload entries below, but keeps dofile() of this file working
-- when the module files exist on disk, e.g. from the test harness).
do
  local agent_dir = debug.getinfo(1, "S").source:match("^@(.*)[/\\][^/\\]+$")
  if not agent_dir or agent_dir == "" then agent_dir = "." end
  package.path = agent_dir .. "/src/?.lua;" .. package.path
end

-- agent.agent.json (embedded module)
package.preload["agent.json"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.json — JSON codec (Phase 2 split).
--
-- Verbatim move of the old agent.lua Section 1. Note: the original
-- code assigns the GLOBAL `json` table and refers to `json.encode`
-- recursively from inside the codec; that is preserved exactly so
-- behavior (and the global for tests) is unchanged. The module also
-- returns the same table, so `require("agent.json")` is usable.
-- ═══════════════════════════════════════════════════════════════

json = {}

-- JSON 字符串转义（模块级映射，避免每次 encode 重建表）
-- 除 \ " \n \r \t 外，所有控制字符（\x00-\x1f、\x7f）必须转义为 \u00XX，
-- 否则裸控制字符产出非法 JSON，服务端解析失败返回 HTTP 400
local ESCAPES = {
  ["\\"] = "\\\\",
  ['"'] = '\\"',
  ["\n"] = "\\n",
  ["\r"] = "\\r",
  ["\t"] = "\\t",
}

-- 缓冲式 encode（内存优化：P0 OOM 修复的治本——旧实现每层 json.encode()
-- 产生完整子串存 parts + 顶层 table.concat 再复制一次，且每个字符串
-- '"'..s..'"' 强制拼接副本；纯文本消息（无转义字符）时 gsub 返回原字符串
-- 引用（零复制），但拼接强制复制。新实现把片段直接 append 进 out 表：
--   1) 无转义的字符串零复制（gsub 无匹配返回原引用），仅最终 concat 一次
--   2) 数组/对象递归 append，不再产生每层子串
-- 峰值从 ~3x 文本降到 ~1.2x（输入原串已存在 + 最终结果一次分配），
-- 真机 55K tokens≈190KB 文本场景 encode 峰值 ~230KB 而非 ~570KB）
local function json_encode_to(out, val)
  local t = type(val)
  if val == nil then
    out[#out + 1] = "null"
  elseif t == "boolean" then
    out[#out + 1] = val and "true" or "false"
  elseif t == "number" then
    if val ~= val or val == math.huge or val == -math.huge then
      out[#out + 1] = "null"
    else
      out[#out + 1] = tostring(val)
    end
  elseif t == "string" then
    -- 无转义字符时 gsub 返回原字符串引用（零复制）——直接进缓冲；
    -- 引号/反斜杠/控制字符才产生转义副本（\u00XX 转义规则不变）
    out[#out + 1] = '"'
    out[#out + 1] = val:gsub("[\\\"%c]", function(c)
      local esc = ESCAPES[c]
      if esc then return esc end
      return string.format("\\u%04x", c:byte())
    end)
    out[#out + 1] = '"'
  elseif t == "table" then
    local is_array = true
    local max_idx = 0
    local has_string_keys = false
    for k in pairs(val) do
      if type(k) == "string" then
        has_string_keys = true
        is_array = false
        break
      end
      if type(k) ~= "number" or k < 1 or k ~= math.floor(k) then
        is_array = false
      end
      if k > max_idx then max_idx = k end
    end
    if is_array and max_idx == #val and not has_string_keys then
      out[#out + 1] = "["
      for i = 1, #val do
        if i > 1 then out[#out + 1] = "," end
        json_encode_to(out, val[i])
      end
      out[#out + 1] = "]"
    else
      out[#out + 1] = "{"
      local first = true
      for k, v in pairs(val) do
        if type(k) == "string" then
          if not first then out[#out + 1] = "," end
          first = false
          json_encode_to(out, k)
          out[#out + 1] = ":"
          json_encode_to(out, v)
        end
      end
      out[#out + 1] = "}"
    end
  else
    error("json: cannot encode type " .. t)
  end
end

function json.encode(val)
  local out = {}
  json_encode_to(out, val)
  return table.concat(out)
end

function json.decode(str)
  local pos = 1
  local n = #str

  -- byte-based 跳过空白（兼容 Lua %s 全集: 空格/Tab/LF/FF/CR/VT——
  -- 与旧版 str:find("^[%s]*") 行为一致）
  local function skip_ws()
    while pos <= n do
      local b = str:byte(pos)
      if b == 32 or b == 9 or b == 10 or b == 11 or b == 12 or b == 13 then
        pos = pos + 1
      else
        break
      end
    end
  end

  local function parse_string()
    pos = pos + 1  -- skip opening quote
    local result = {}
    while pos <= n do
      local b = str:byte(pos)
      if b == 34 then  -- closing quote
        pos = pos + 1
        return table.concat(result)
      elseif b == 92 then  -- backslash escape
        pos = pos + 1
        local esc = str:sub(pos, pos)
        if esc == "n" then result[#result+1] = "\n"
        elseif esc == "r" then result[#result+1] = "\r"
        elseif esc == "t" then result[#result+1] = "\t"
        elseif esc == '"' then result[#result+1] = '"'
        elseif esc == "\\" then result[#result+1] = "\\"
        elseif esc == "/" then result[#result+1] = "/"
        elseif esc == "u" then
          local hex = str:sub(pos+1, pos+4)
          pos = pos + 4
          local code = tonumber(hex, 16)
          if code then
            if code < 128 then
              result[#result+1] = string.char(code)
            elseif code < 2048 then
              result[#result+1] = string.char(192 + math.floor(code/64), 128 + code%64)
            else
              result[#result+1] = string.char(224 + math.floor(code/4096), 128 + math.floor(code/64)%64, 128 + code%64)
            end
          end
        else
          result[#result+1] = esc
        end
        pos = pos + 1
      else
        -- 批量收集普通字符段（byte 定位边界，一次 sub 取整段——
        -- 替代逐字符 sub，消除每字符 1 个临时字符串对象）
        local start = pos
        while pos <= n do
          local b2 = str:byte(pos)
          if b2 == 34 or b2 == 92 then break end
          pos = pos + 1
        end
        result[#result+1] = str:sub(start, pos - 1)
      end
    end
    error("json: unterminated string")
  end

  local function parse_number()
    local start = pos
    if str:byte(pos) == 45 then pos = pos + 1 end  -- '-'
    while pos <= n do
      local b = str:byte(pos)
      -- 0-9 e E + - .（与旧版 c:match("[0-9eE+%.%-]") 一致）
      if (b >= 48 and b <= 57) or b == 101 or b == 69 or b == 43 or b == 45 or b == 46 then
        pos = pos + 1
      else
        break
      end
    end
    return tonumber(str:sub(start, pos - 1))
  end

  local parse_value

  local function parse_array()
    pos = pos + 1
    local arr = {}
    skip_ws()
    if str:byte(pos) == 93 then pos = pos + 1; return arr end  -- ']'
    while true do
      arr[#arr + 1] = parse_value()
      skip_ws()
      local c = str:byte(pos)
      if c == 93 then pos = pos + 1; return arr end
      if c ~= 44 then error("json: expected ',' or ']' at " .. pos) end  -- ','
      pos = pos + 1
      skip_ws()
    end
  end

  local function parse_object()
    pos = pos + 1
    local obj = {}
    skip_ws()
    if str:byte(pos) == 125 then pos = pos + 1; return obj end  -- '}'
    while true do
      skip_ws()
      if str:byte(pos) ~= 34 then error("json: expected key string at " .. pos) end  -- '"'
      local key = parse_string()
      skip_ws()
      if str:byte(pos) ~= 58 then error("json: expected ':' at " .. pos) end  -- ':'
      pos = pos + 1
      skip_ws()
      obj[key] = parse_value()
      skip_ws()
      local c = str:byte(pos)
      if c == 125 then pos = pos + 1; return obj end
      if c ~= 44 then error("json: expected ',' or '}' at " .. pos) end
      pos = pos + 1
    end
  end

  parse_value = function()
    skip_ws()
    local c = str:byte(pos)
    if c == 34 then return parse_string()      -- '"'
    elseif c == 123 then return parse_object()  -- '{'
    elseif c == 91 then return parse_array()    -- '['
    -- 关键字必须完整匹配（byte 只验证首字节，后续仍需校验——
    -- 否则 "tru"/"f"/"n" 会被错误接受）
    elseif c == 116 and str:sub(pos, pos + 3) == "true" then pos = pos + 4; return true
    elseif c == 102 and str:sub(pos, pos + 4) == "false" then pos = pos + 5; return false
    elseif c == 110 and str:sub(pos, pos + 3) == "null" then pos = pos + 4; return nil
    elseif c == 45 or (c >= 48 and c <= 57) then return parse_number()
    else error("json: unexpected char at " .. pos) end
  end

  local result = parse_value()
  skip_ws()
  if pos <= #str then error("json: trailing data at " .. pos) end
  return result
end

return json
end

-- agent.agent.http (embedded module)
package.preload["agent.http"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.http — HTTP client (Phase 2 split).
--
-- Verbatim move of the old agent.lua Section 2 (http_post_once +
-- http_post with retry/backoff), renamed exports to { post = ... }.
-- Constants MAX_RETRIES / RETRY_BASE_DELAY live here.
--
-- Depends on agent.json (declared with a local require, never the
-- global): the request body passed to post() is pre-encoded JSON.
-- ═══════════════════════════════════════════════════════════════

local json = require("agent.json")
local interrupt = require("agent.interrupt")  -- v0.3.86: Ctrl+C 中断支持

-- ═══════════════════════════════════════════════════════════════
-- Retry policy（参考 opencode src/session/retry.ts 指数退避重试:
-- 2000ms 基数 ×2，瞬态失败无限重试直到成功或不可重试错误）:
--   - 瞬态 = 网络错误 / HTTP 429 / 5xx；4xx 永久失败不重试
--   - 总重试预算 retry_budget 秒（生产默认 300s，config.retry_budget
--     可调——chat() 每次请求前同步，热更新生效；测试环境 _TEST_MODE
--     默认 60s）。预算耗尽返回最后一次结果。opencode 无总预算（单请求
--     可挂 24 天），但 OC 单线程场景必须有界：3600s（1h）对交互式
--     TUI 是"无反馈挂起 1 小时"；300s（5 分钟）折中——端点瞬态故障
--     足够，超时返回最后结果让用户看到错误
--   - 单次等待封顶 RETRY_DELAY_CAP（300s），避免极端退避
-- 讯飞星辰等免费端点频繁 429/慢响应，需要更长的重试窗口。
-- ═══════════════════════════════════════════════════════════════
local RETRY_BASE_DELAY = 2         -- 指数退避基数（秒）
local RETRY_DELAY_CAP = 300        -- 单次等待封顶（秒）
-- 总重试预算: 生产默认 300s；测试环境（_TEST_MODE）缩短为 60s，
-- 避免 e2e/回归在端点持续故障时长时间挂起。chat() 每次请求前用
-- config.retry_budget 覆盖（热更新）
local retry_budget = _TEST_MODE and 60 or 300
-- 单次请求响应读超时（秒）: 真机荒野大师 internet 迭代器可能在连接
-- 建立后流不结束（JVM 实现可能无 OS 超时）——响应迭代若无超时则无限
-- 等，而重试预算检查（os.clock()）在 once 返回后才执行，预算形同虚设。
-- 默认 120s；config.response_timeout 可调（chat() 每次请求前同步）
local MAX_RESPONSE_WAIT = 120
-- 单次请求响应体累积上限（字节）: 结构性内存护栏——OOM 无法预测（单次
-- 工具调用/响应峰值不可知），正确解法是给所有已知分配源设硬上限，任何
-- 单次峰值都落在安全线内。http_post_once 的 chunks 累积此前无上限，
-- max_tokens 8192 的 reasoning 响应 JSON 可能 100KB+，decode 峰值 2-3x
-- 单次就爆（真机 2MB 内存）。默认 131072（128KB）——合法响应 ≈60KB
-- 足够容纳且防爆。超限返回明确 error（不静默截断——截断的 JSON 会解析
-- 失败，明确 error 让 chat() 走错误路径）。config.response_body_limit
-- 可调（chat() 每次请求前同步）
local MAX_RESPONSE_BODY = 131072

-- Single request attempt. Returns code, body, err.
local function http_post_once(url, headers, body)
  local internet = require("internet")
  local ok, handle = pcall(function()
    -- 3-arg form: body presence auto-selects POST (compatible with ocvm
    -- and real OC; explicit 4th method arg is ignored by some emulators)
    return internet.request(url, body, headers)
  end)
  if not ok then
    return nil, nil, "connection failed: " .. tostring(handle)
  end

  local chunks = {}
  local timed_out = false
  local too_large = false
  local interrupted = false
  local iter_ok, iter_err = pcall(function()
    local n = 0
    -- 响应迭代 deadline（挂起保护）: 荒野大师 JVM internet 迭代器连接
    -- 建立后流可能永不结束，无超时则无限等（重试预算检查不到——预算在
    -- once 返回后才执行）。保持每 chunk os.sleep(0.02) yield——OC 调度器
    -- 看到进展，避免 "too long without yielding" 崩溃。
    local read_deadline = os.clock() + MAX_RESPONSE_WAIT
    local total = 0
    for chunk in handle do
      -- v0.3.86: Ctrl+C 中断——interrupt.install() 补丁的 os.sleep 检测到
      -- interrupted 事件设标志; 每 chunk 检查, 提前终止响应读取
      if interrupt.poll() then
        interrupted = true
        return
      end
      if os.clock() >= read_deadline then
        timed_out = true
        return
      end
      -- 响应体累积字节检查（结构性上限）: 任何单次响应峰值不得超过
      -- MAX_RESPONSE_BODY——超限立即返回明确 error（不静默截断，截断的
      -- JSON 解析失败只会让错误更难诊断）。与超时 deadline 共存。
      total = total + #chunk
      if total > MAX_RESPONSE_BODY then
        too_large = true
        return
      end
      n = n + 1
      chunks[#chunks + 1] = chunk
      -- Yield on EVERY chunk: OC's scheduler sees progress even while the
      -- iterator waits for slow (reasoning) model responses. Otherwise the
      -- computer crashes with "too long without yielding".
      os.sleep(0.02)
    end
  end)
  if not iter_ok then
    return nil, nil, "http read failed: " .. tostring(iter_err)
  end
  if timed_out then
    return nil, nil, "http read timeout after " .. tostring(MAX_RESPONSE_WAIT) .. "s"
  end
  if too_large then
    return nil, nil, "http response too large (>" .. tostring(MAX_RESPONSE_BODY) .. " bytes)"
  end
  if interrupted then
    interrupt.clear()
    return nil, nil, "interrupted"
  end
  local response_body = table.concat(chunks)

  -- Some emulators (ocvm) fill the response asynchronously; retry briefly.
  local code
  local mt = getmetatable(handle)
  if mt and mt.__index and mt.__index.response then
    for _ = 1, 10 do
      -- v0.3.86: 中断检查（补丁 os.sleep 已设标志）
      if interrupt.poll() then
        interrupt.clear()
        return nil, nil, "interrupted"
      end
      local ok2, c = pcall(mt.__index.response)
      if ok2 and type(c) == "number" then
        code = c
        break
      end
      os.sleep(0.2)
    end
  end

  return code or 0, response_body, nil
end

-- POST with automatic retry（指数退避 + 总预算上限）
local function http_post(url, headers, body)
  local attempt = 0
  local deadline = os.clock() + retry_budget
  while true do
    attempt = attempt + 1
    local code, resp, err = http_post_once(url, headers, body)
    -- v0.3.86: 用户中断——不重试，直接返回（Ctrl+C 语义: 立即停）
    if err == "interrupted" then
      return code, resp, err
    end
    local transient = err ~= nil or code == 429 or (code and code >= 500)
    if not transient then
      return code, resp, err
    end
    local now = os.clock()
    if now >= deadline then
      -- 预算耗尽: 返回最后一次结果（调用方按错误处理）
      return code, resp, err
    end
    local wait = RETRY_BASE_DELAY * 2 ^ (attempt - 1)
    if wait > RETRY_DELAY_CAP then wait = RETRY_DELAY_CAP end
    local remaining = deadline - now
    if wait > remaining then wait = remaining end
    os.sleep(wait)
  end
end

-- 运行时策略调整（config 热更新: chat() 每次请求前调用）
local function set_budget(b)
  retry_budget = b
end

local function set_response_timeout(t)
  MAX_RESPONSE_WAIT = t
end

local function set_response_body_limit(b)
  MAX_RESPONSE_BODY = b
end

return {
  post = http_post,
  set_budget = set_budget,
  set_response_timeout = set_response_timeout,
  set_response_body_limit = set_response_body_limit,
}
end

-- agent.agent.config (embedded module)
package.preload["agent.config"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.config — configuration + writable-base detection (Phase 2
-- split).
--
-- Verbatim move of the old agent.lua Section 6 config parts:
-- find_writable_base / load_config / save_config / first_run_setup.
-- find_writable_base() runs ONCE at module load (top-level side
-- effect, same order as the old single-file Section 6) and the
-- resolved paths are exported for agent.lua (and tests).
--
-- Depends on require("filesystem").
-- ═══════════════════════════════════════════════════════════════

-- Paths. If /home is not writable (OpenOS not installed to a writeable
-- medium), fall back to the first writable mount (tmpfs/hdd).
local function find_writable_base()
  local fs = require("filesystem")
  -- probe /home first
  local f = io.open("/home/agent_write_probe.txt", "w")
  if f then f:close(); os.remove("/home/agent_write_probe.txt"); return "/home" end
  -- iterate mounts: iterator yields (proxy, mount_path)
  for _, mount in fs.mounts() do
    if mount and mount ~= "/" then
      local probe = mount .. "/agent_write_probe.txt"
      local f2 = io.open(probe, "w")
      if f2 then
        f2:close()
        os.remove(probe)
        return mount
      end
    end
  end
  return "/home"  -- give up; callers will handle write errors
end

-- Top-level side effect (module load time): probe the writable base once.
-- data_dir 引导（2026-08-10 磁盘迁移功能）: 原盘 config 里若有 data_dir
-- 且该目录可写（/relocate 迁移后写入的引导项），则所有数据路径
-- （config/history/sessions）切换到目标盘。目标盘不可写（盘被拔/只读）
-- 时回退原盘——自动容错。
-- 验证（2026-08-10 ocvm）: ①m01467 首次启动 + config 含 data_dir →
--   /relocate 显示"当前数据目录: /tmp"切换生效；②独立探针复刻
--   find_writable_base+probe_data_dir 全部步骤通过（base 探测 → config
--   读取 → unserialize → 目标可写）。此前"重启后未切换"均为测试驱动
--   假象（tmux capture-pane 含屏幕历史，"Goodbye!/home #"是旧残留，
--   lua agent.lua 被旧 TUI 当聊天消息——进程从未真正重启）。
local function probe_data_dir(base)
  local fs = require("filesystem")
  local f = io.open(base .. "/agent_config.txt", "r")
  if not f then return base end
  local content = f:read("*a")
  f:close()
  local ser = require("serialization")
  local ok, d = pcall(ser.unserialize, content)
  if not ok or type(d) ~= "table" or type(d.data_dir) ~= "string" or d.data_dir == "" then
    return base
  end
  local target = d.data_dir
  if target == base then return base end
  local probe = io.open(target .. "/wprobe.txt", "w")
  if probe then
    probe:close()
    os.remove(target .. "/wprobe.txt")
    print("[relocate] 数据目录由 " .. base .. " 切换到 " .. target .. "（config.data_dir）")
    return target
  end
  return base
end
local writable_base = probe_data_dir(find_writable_base())
local config_path = writable_base .. "/agent_config.txt"
local history_path = writable_base .. "/agent_history.txt"
local sessions_dir = writable_base .. "/sessions"

-- 内存自适应缩放（2026-08-10，真机升级 4MB 后）: 全部内存类默认阈值
-- 按 totalMemory/2MB 缩放（2MB 基准调校值 × scale）——4MB 机器
-- scale=2: 阈值翻倍（更大历史/更大响应体/更晚折叠），2MB 机器
-- scale=1 行为不变；同一 agent.lua 免改配置。显式配置优先
--（load() 中 `if not data.X` 只在缺省时填缩放值）。
-- 探测失败（精简/测试环境无 totalMemory）→ scale=1 安全回退。
local function detect_mem_scale()
  local ok_c, computer = pcall(require, "computer")
  if ok_c and computer and computer.totalMemory then
    local ok_t, total = pcall(computer.totalMemory)
    if ok_t and type(total) == "number" and total > 0 then
      return total / 2097152
    end
  end
  return 1
end
local MEM_SCALE = detect_mem_scale()

local function load()
  local fs = require("filesystem")
  if not fs.exists(config_path) then return nil end
  local f = io.open(config_path, "r")
  if not f then return nil end
  local content = f:read("*a")
  f:close()
  local ser = require("serialization")
  local ok, data = pcall(ser.unserialize, content)
  if ok and type(data) == "table" then
    -- 默认值（/ctx 上下文显示用；模型窗口按实际配置）
    -- 模型上下文窗口（token）: /ctx 显示、60% 压缩引导、80% 硬保护、
    -- 请求估算的基准。**窗口是模型属性，与硬件无关，不随内存自动缩放**
    -- ——在 4MB 机器跑 200K 上下文需显式配置 context_window=200000
    --（字节类阈值已按内存 scale² 放大：4MB 下 byte_budget/prefold/
    -- load_budget=800KB，足以承载 200K tokens ≈700KB 中文历史）。
    if not data.context_window then data.context_window = 128000 end
    -- 运行时自动显示上下文（每次响应后一行 [ctx]），可设 false 关闭
    if data.ctx_auto == nil then data.ctx_auto = true end
    -- 内存压力压缩阈值（字节）: freeMemory() 低于此值即强制折叠早期消息
    -- （真机 OOM→error 根因修复；默认 400KB×scale——OC 1.4MB 内存下
    -- encode 峰值 137-230KB，真机低谷 278KB 时 encode 必超限；4MB
    -- 机器 800KB，内存充裕时更晚触发）
    if not data.mem_compact_threshold then
      data.mem_compact_threshold = math.floor(400000 * MEM_SCALE)
    end
    -- 内存压力物理裁剪阈值（字节）: mem_pressure 触发时历史表裁剪到该值
    -- 以下（真机第二次 OOM 修复——折叠只缩请求体不释放内存；默认
    -- 60KB×scale，裁剪后 encode 峰值大幅下降，缓存前缀 miss 一次保命）
    if not data.mem_trim_bytes then
      data.mem_trim_bytes = math.floor(60000 * MEM_SCALE)
    end
    -- 历史加载内存上限（字节）: load_history 解析后表裁剪到该值以下
    -- （93.6KB JSONL 全量加载 → 表 ~300KB；默认 200KB×scale²——4MB
    -- 机器 800KB：足以装载 200K tokens 中文历史（≈700KB）进内存表；
    -- JSONL 文件 append-only 完整保留，只限内存表）
    if not data.mem_load_budget then
      data.mem_load_budget = math.floor(200000 * MEM_SCALE * MEM_SCALE)
    end
    -- 传统自动压缩字节阈值（mem_prefold_bytes）: 表字节超此值即系统自动
    -- 折叠（opencode 传统模式——不等模型调 compact_history 工具；模型
    -- 需 ≥60% 窗口才自觉压缩，OC 内存下永远到不了）。默认 200KB×scale²
    --（2026-08-10: 内存翻倍 → 可承载请求体 4 倍——4MB 机器 800KB 才
    -- 折叠，配合用户配置 context_window=200000 可跑 200K 上下文；
    -- 2MB 机器 scale=1 时 200KB 略高于旧 100KB——2MB 下编码峰值
    -- 137-230KB 实测仍安全，且 byte_budget 兜底裁剪），先于 mem_pressure
    -- 裁剪触发（宽裕期保上下文）；折叠段物理回收后表字节真实下降。
    if not data.mem_prefold_bytes then
      data.mem_prefold_bytes = math.floor(200000 * MEM_SCALE * MEM_SCALE)
    end
    -- 摘要请求专用输出预算（summary_max_tokens）: deepseek 强思考模型下
    -- opencode 的 4096 不够——reasoning 先吃大部分输出预算，可见摘要
    -- content 被挤掉 → 摘要残缺 → 上下文没压住 → 重复压缩。默认 16384。
    -- 摘要响应**不持久化**（只提取 content 写入摘要消息），128KB 响应体
    -- 上限（response_body_limit）已保护——与主请求 max_tokens 8192（长
    -- reasoning 进历史 → 下次请求 encode 体积暴涨 → OOM）不同场景，
    -- 专用大 max_tokens 无 OOM 风险。config 可调。
    if not data.summary_max_tokens then data.summary_max_tokens = 16384 end
    -- HTTP 重试总预算（秒）: 交互式 TUI 场景默认 300s（5 分钟）。原
    -- 3600s（1h）对端点持续故障是"无反馈挂起 1 小时"；300s 折中——
    -- 端点瞬态故障足够，超时返回最后结果让用户看到错误。需要长时间
    -- 容忍免费端点限流的用户可调大（上限不强制）。
    if not data.retry_budget then data.retry_budget = 300 end
    -- 单次请求响应读超时（秒）: 真机荒野大师 internet 迭代器可能连接
    -- 建立后流不结束（JVM 实现无 OS 超时），响应迭代无超时则无限等。
    -- 默认 120s。
    if not data.response_timeout then data.response_timeout = 120 end
    -- 单次请求响应体累积上限（字节）: 结构性内存护栏——OOM 无法预测
    -- （单次响应峰值不可知），硬上限保证任何单次峰值都落在安全线内。
    -- max_tokens 8192 的 reasoning 响应 JSON 可能 100KB+，decode 峰值
    -- 2-3x 单次就爆（真机 2MB 内存）；默认 131072×scale（2MB=128KB，
    -- 4MB=256KB）——合法响应 ≈60KB 足够容纳且防爆。超限返回明确 error
    -- （不静默截断）。
    if not data.response_body_limit then
      data.response_body_limit = math.floor(131072 * MEM_SCALE)
    end
    return data
  end
  return nil
end

local function save(config)
  local ser = require("serialization")
  local f = io.open(config_path, "w")
  if not f then error("cannot save config") end
  f:write(ser.serialize(config))
  f:close()
end

local function first_run()
  print("OC Agent - First Run Setup")
  io.write("API Key (empty for free OpenCode Zen model, or any OpenAI-compatible key): ")
  local api_key = io.read():gsub("\n", "")
  io.write("Model [deepseek-v4-flash-free]: ")
  local model = io.read():gsub("\n", "")
  if model == "" then model = "deepseek-v4-flash-free" end
  io.write("API URL [https://opencode.ai/zen/v1/chat/completions]: ")
  local api_url = io.read():gsub("\n", "")
  if api_url == "" then api_url = "https://opencode.ai/zen/v1/chat/completions" end

  local config = {api_key = api_key, model = model, api_url = api_url}
  save(config)
  print("Configuration saved to " .. config_path)
  return config
end

return {
  load = load,
  save = save,
  first_run = first_run,
  writable_base = writable_base,
  config_path = config_path,
  history_path = history_path,
  sessions_dir = sessions_dir,
  -- 内存自适应缩放系数（totalMemory/2MB）: session.lua/init.lua 硬常量
  -- 同步缩放（MAX_HISTORY/MAX_HISTORY_BYTES/MAX_LOAD_HISTORY 等）
  mem_scale = MEM_SCALE,
}
end

-- agent.agent.session (embedded module)
package.preload["agent.session"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.session — conversation history + compaction (Phase 2 split).
--
-- Verbatim move of the old agent.lua Section 6 history parts
-- (load/append/rebuild_history, trim_history, MAX_* constants) and
-- Section 5.5 compaction (summarize/compact/should_compact).
--
-- Dependencies: agent.json (message encode/decode), agent.config
-- (default history_path). chat is INJECTED via set_chat() (agent.lua
-- Section 5) because summarize_history routes its LLM call through the
-- shared chat client; it is nil-safe when not injected yet.
--
-- set_paths() replaces the old agent_test HISTORY_PATH rebinding hack:
-- the module owns its history path state.
-- ═══════════════════════════════════════════════════════════════

local json = require("agent.json")
local config_mod = require("agent.config")

-- Injected by agent.lua's set_chat(chat) once Section 5 is defined.
local injected_chat
-- History path state: defaults to the config module's resolved path,
-- overridable via set_paths (used by tests).
local history_path = config_mod.history_path

-- 历史/trim 预算（OC 内存约束）与压缩触发（模型窗口约束）:
--   - trim: 200KB / 60 条 —— 2MB 内存下历史+编码峰值 ~600KB，安全
--   - 压缩: 窗口比例驱动（估算 tokens ≥ 窗口 60%）+ 条数 48 兜底
-- 梯度保持: 压缩触发点 < trim 截断点。旧固定阈值（16条/40KB）导致每轮
-- 工具对话必压缩 → 每轮调 LLM 摘要 + 破坏缓存前缀。
-- 内存自适应缩放（2026-08-10 真机 4MB 升级 + 200K 上下文目标）:
-- 硬常量按 config_mod.mem_scale（= totalMemory/2MB）的**平方**缩放——
-- 内存翻倍 → 可承载请求体 4 倍（4MB 机器 MAX_HISTORY=480 条/1.2MB
-- 历史表，配合用户 context_window=200000 达成 200K 上下文；2MB 机器
-- scale=1 时 120 条/300KB——比旧 60 条/200KB 大，字节预算与编码峰值
-- 实测安全）。显式 config（mem_load_budget 等）仍优先——此处仅模块级
-- 硬常量。
local MEM_SCALE = config_mod.mem_scale or 1
local MEM_SCALE2 = MEM_SCALE * MEM_SCALE
local MAX_HISTORY = math.floor(120 * MEM_SCALE2)
local MAX_HISTORY_BYTES = math.floor(300000 * MEM_SCALE2)  -- ~300KB×scale²; 4MB=1.2MB 历史表（200K 上下文装载）
local MAX_TOOL_RESULT = 3000     -- per-tool-result cap (exported: agent.lua uses it in process_exchange)
-- head+tail 双保（reasonix 借鉴）: 超限结果保留前/后各 TOOL_RESULT_KEEP 字节，
-- 总预算与 MAX_TOOL_RESULT 一致（3000），中间部分以标记提示。
local TOOL_RESULT_KEEP = 1500

local COMPACT_KEEP = 4          -- 保留条数下限
local COMPACT_KEEP_MIN_TOKENS = 1500  -- 保留 token 保底（不足时向前补充，
                                      -- opencode-acp 的条数+token 双轨思路）
local COMPACT_KEEP_MAX = 8      -- 保留条数封顶（防小消息全保留、压缩无效）
local COMPACT_TRIGGER_COUNT = 48  -- 条数兜底（trim 60 条的 80%，防海量小消息退化）
local COMPACT_WINDOW_RATIO = 0.6  -- 主触发: 估算 tokens ≥ 窗口 × 0.6（tokens 上限阈值驱动）

-- 估算 token（唯一实现，init.lua 引用本模块导出）: 英文 ~4 字符/token，
-- 中文按 0.45 token/字节
local function estimate_tokens(s)
  if not s then return 0 end
  s = tostring(s)
  local ascii, non_ascii = 0, 0
  for i = 1, #s do
    if s:byte(i) < 128 then ascii = ascii + 1 else non_ascii = non_ascii + 1 end
  end
  return math.floor(ascii / 4 + non_ascii * 0.45)
end

local function msg_bytes(msg)
  local total = 0
  if type(msg.content) == "string" then total = total + #msg.content end
  if type(msg.tool_calls) == "table" then
    for _, tc in ipairs(msg.tool_calls) do
      if tc["function"] and type(tc["function"].arguments) == "string" then
        total = total + #tc["function"].arguments
      end
    end
  end
  return total
end

local function trim_history(messages)
  -- Cap by count first — 保留 messages[1]（首个 user 消息 = 前缀缓存锚点，
  -- 裁剪会破坏缓存前缀，锚定头部让命中跨裁剪存活）
  if #messages > MAX_HISTORY then
    local trimmed = {messages[1]}
    for i = #messages - MAX_HISTORY + 2, #messages do
      trimmed[#trimmed + 1] = messages[i]
    end
    messages = trimmed
  end
  -- Then cap by total bytes; 优先丢折叠段消息（已进摘要，删除无损——
  -- folded 分支保留为无害兼容，折叠段已由 compact_history 物理删除，
  -- 此路径实际不触发），其次从头丢；保留 messages[1] 与最近消息
  while #messages > 3 do  -- keep the first message + the last 2 (current exchange)
    local total = 0
    for _, m in ipairs(messages) do
      total = total + msg_bytes(m)
    end
    if total <= MAX_HISTORY_BYTES then break end
    local target = nil
    for i = 2, #messages - 2 do
      if messages[i].folded then target = i break end
    end
    table.remove(messages, target or 2)
  end
  return messages
end

-- 物理裁剪到字节预算（保内存优先，OC 2MB 内存约束）: 保留 messages[1]
-- （前缀缓存锚点），从第 2 条起无条件删除（folded 段也删——已进摘要，
-- 且本函数目的就是释放内存），直到总字节 ≤ budget 或只剩 MEM_MIN_KEEP 条。
-- 与 trim_history 的"优先丢折叠段"语义分层:
--   折叠（compact_history 字节阈值 / ensure_context_budget 窗口路径 /
--     模型 compact_history 工具）→ 物理删除折叠段（摘要承载内容），
--     缓存前缀随摘要位置变化 miss 一次——传统自动压缩语义（opencode 同）；
--   物理裁剪（mem_pressure 内存紧张 / load_history 加载上限）→ 无条件
--     释放内存，缓存前缀同样 miss——真机已 OOM 两次（v0.3.45 折叠不
--     释放内存是第二次根因，gist 10d45721），保命优先。
-- JSONL 文件不受影响（append-only 保留完整历史，只动内存表）。
-- 返回裁剪后总字节。
local MEM_MIN_KEEP = 5  -- 最低保留（锚点 + 最近 4 条，与 force_trim 一致）
local function trim_to_bytes(messages, budget)
  local total = 0
  for _, m in ipairs(messages) do total = total + msg_bytes(m) end
  local guard = 0
  while #messages > MEM_MIN_KEEP and total > budget and guard < 10000 do
    guard = guard + 1
    total = total - msg_bytes(messages[2])
    table.remove(messages, 2)
  end
  -- 只剩 MEM_MIN_KEEP 条仍超预算（个别超大消息）: 保锚点 + 最近消息兜底
  while #messages > 3 and total > budget and guard < 10000 do
    guard = guard + 1
    total = total - msg_bytes(messages[2])
    table.remove(messages, 2)
  end
  return total
end

-- 构建发送给摘要模型的 transcript，返回 {text, parts}——parts[i] 是 text
-- 第 i 行对应的原始消息（KEEP 展开时按行号找回原文）。纯函数:
-- compact_history 与 summarize_history 对同一批消息调用结果一致。
local function build_transcript(messages)
  local parts, text_parts = {}, {}
  for _, m in ipairs(messages) do
    local role = m.role or "?"
    local content = ""
    if m.content and m.content ~= "" then
      content = m.content
    elseif m.tool_calls then
      local names = {}
      for _, tc in ipairs(m.tool_calls) do
        names[#names + 1] = (tc["function"] and tc["function"].name) or "?"
      end
      content = "[tool_calls: " .. table.concat(names, ", ") .. "]"
    elseif m.role == "tool" then
      content = tostring(m.content):sub(1, 200)
    end
    if content ~= "" then
      parts[#parts + 1] = m
      text_parts[#text_parts + 1] = string.format("[%d] %s: %s", #parts, role, content)
    end
  end
  local text = table.concat(text_parts, "\n")
  -- Cap what we send to the summarizer
  if #text > 12000 then
    text = text:sub(1, 12000) .. "\n...[truncated]"
  end
  return {text = text, parts = parts}
end

-- Ask the LLM to summarize older messages. Independent minimal request
-- (no tools, no runtime block, no main system prompt — only the summary
-- instruction + transcript, via chat() opts) so it can't recurse into
-- compaction. Returns summary string or nil on failure (empty summary
-- after one retry, or transport error).
local function summarize_history(messages, config, previous_summary)
  local transcript = build_transcript(messages).text

  -- Anchored summary (opencode-style): when a previous summary exists, ask the
  -- model to UPDATE it instead of summarizing from scratch. Keeps older facts
  -- stable and saves tokens. KEEP/REF 指令（opencode-acp 移植）: KEEP 行号标记
  -- 嵌入关键原文，REF 行号标记做省 token 的引用指针；压缩后由
  -- expand_keep_markers 展开。七节骨架（reasonix compact 借鉴）。
  local sys_prompt = "You are a conversation summarizer for an AI agent running inside OpenComputers (Minecraft). Keep: user goals and questions, decisions, tool results that matter, file paths, component addresses, and any constraints. Preserve factual details. Output only the summary, no preamble.\n\nOrganize the summary with these sections: Standing facts（持续成立的事实）、Goal（当前目标）、Decisions（已做的决定及理由）、Files（涉及的文件与改动）、Commands（重要命令）、Errors（关键错误与教训）、Pending（未完成事项）。Omit sections that have nothing to report.\n\nTranscript lines are numbered [N]. If any message is critical to preserve VERBATIM (exact tool result, exact error text, exact user request), inline it in the summary with a marker: [[KEEP:N]] followed by the original text in quotes. For less critical messages, reference them cheaply with [[REF:N|简短描述]] instead of embedding the full text. Use at most 3 KEEP markers and at most 5 REF markers."
  local user_prompt
  if previous_summary and previous_summary ~= "" then
    sys_prompt = "You maintain an anchored summary for an AI agent conversation. Update the previous summary below using the new conversation history: keep still-true details, remove stale ones, merge new facts. Keep it concise. Output only the updated summary.\n\nOrganize the summary with these sections: Standing facts（持续成立的事实）、Goal（当前目标）、Decisions（已做的决定及理由）、Files（涉及的文件与改动）、Commands（重要命令）、Errors（关键错误与教训）、Pending（未完成事项）。Omit sections that have nothing to report.\n\nTranscript lines are numbered [N]. If any message is critical to preserve VERBATIM (exact tool result, exact error text, exact user request), inline it with a marker: [[KEEP:N]] followed by the original text in quotes. For less critical messages, reference them cheaply with [[REF:N|简短描述]] instead of embedding the full text. Use at most 3 KEEP markers and at most 5 REF markers."
    user_prompt = "<previous-summary>\n" .. previous_summary .. "\n</previous-summary>\n\n<new-history>\n" .. transcript .. "\n</new-history>\n\nUpdate the summary."
  else
    user_prompt = "Summarize this conversation:\n\n" .. transcript
  end

  -- Route through the injected chat() (set via set_chat) so session.lua does
  -- not need its own HTTP stack; chat is nil until agent.lua finishes Section 5.
  -- 摘要请求专用瘦身路径（opencode 裸摘要请求同款 + reasonix 'independent
  -- minimal request ... so it can't recurse into compaction' 防递归）:
  --   主请求带 ~5KB system + ~1KB runtime 尾块 + ~10KB tools 声明，摘要
  --   请求全部跳过 → 请求体只剩 [摘要指令 system + transcript user] ≈1KB；
  --   max_tokens 用摘要专用预算（config.summary_max_tokens 默认 16384）——
  --   deepseek 强思考模型下 opencode 的 4096 不够（reasoning 先吃大部分
  --   输出预算，可见摘要 content 被挤掉 → 摘要残缺 → 重复压缩）。
  -- 摘要响应**不持久化**（只提取 content 写摘要消息），128KB 响应体上限
  -- （response_body_limit）已保护——与主请求 8192（长 reasoning 进历史 →
  -- encode OOM）不同场景，专用大 max_tokens 无 OOM 风险。
  local chat = injected_chat
  if type(chat) ~= "function" then return nil end
  local summary_opts = {
    skip_system = true,
    skip_runtime = true,
    skip_tools = true,
    max_tokens = tonumber(config.summary_max_tokens) or 16384,
  }
  -- 请求一次摘要: 返回 (summary, fatal)。fatal=true = 传输/HTTP 失败
  -- （不重试）；fatal=nil + summary=nil = content 空/空白（thinking 模型
  -- reasoning 挤占输出预算的典型表现，可重试）。
  local function request_summary(hint)
    local prompt = user_prompt
    if hint then prompt = prompt .. "\n\n" .. hint end
    local response = chat({
      {role = "system", content = sys_prompt},
      {role = "user", content = prompt}
    }, config, summary_opts)
    if type(response) ~= "table" then return nil, true end
    if response.error then return nil, true end
    local s = response.content
    if not s or s:gsub("%s", "") == "" then return nil end
    return s
  end

  local summary, fatal = request_summary(nil)
  if not summary then
    if fatal then return nil end  -- 传输失败: 不重试（与空摘要区分）
    -- 空摘要兜底（v0.3.33 空回答重试网简化版，摘要专用一次重试）:
    -- thinking 模型 reasoning 挤占输出预算时 content 空/空白——注入
    -- "直接输出摘要"提示再调一次；仍空返回 nil → compact_history 走
    -- trim 兜底（force_trim/字节裁剪），不阻断压缩流程。
    print("[compact] 摘要为空（可能被 reasoning 挤占），重试一次...")
    summary, fatal = request_summary(
      "Please output the summary directly as plain text now. Do not output reasoning/thinking content.")
    if not summary then
      print("[compact] 摘要重试仍" .. (fatal and "失败" or "为空")
        .. "，放弃压缩（调用方走 trim 兜底）")
      return nil
    end
  end
  return summary
end

-- KEEP/REF 标记展开（opencode-acp keep-markers 移植）: 摘要里的 [[KEEP:N]]
-- 替换为对应消息原文（截断 KEEP_EMBED_MAX_CHARS）；[[REF:N|desc]] 只展开为
-- 引用指针 "[消息 N] desc"（描述来自摘要本身，不嵌入原文——省 token）。
-- 越界引用保留原样并警告（非阻塞质量门——引用解析率是压缩质量指标，
-- 失败不阻断压缩）。
local KEEP_PATTERN = "%[%[KEEP:(%d+)%]%]"
local REF_PATTERN = "%[%[REF:(%d+)%|([^%]]-)%]%]"
local KEEP_EMBED_MAX_CHARS = 1000

local function expand_keep_markers(summary, transcript_parts)
  summary = (summary:gsub(KEEP_PATTERN, function(idx_s)
    local idx = tonumber(idx_s)
    local m = transcript_parts and transcript_parts[idx]
    if not m then
      print("[compact] KEEP 引用越界: " .. idx_s)
      return "[[KEEP:" .. idx_s .. "]]"
    end
    local content = ""
    if type(m.content) == "string" then
      content = m.content
    elseif m.tool_calls then
      local names = {}
      for _, tc in ipairs(m.tool_calls) do
        names[#names + 1] = (tc["function"] and tc["function"].name) or "?"
      end
      content = "[tool_calls: " .. table.concat(names, ", ") .. "]"
    end
    if #content > KEEP_EMBED_MAX_CHARS then
      content = content:sub(1, KEEP_EMBED_MAX_CHARS)
        .. "\n...[truncated, " .. #content .. " chars total]"
    end
    local label = m.role or "?"
    return "\n--- [KEEP:" .. idx_s .. ": " .. label .. "] ---\n"
      .. content .. "\n--- end ---\n"
  end))
  -- REF 引用指针: 展开为 "[消息 N] desc"（不嵌原文）
  return (summary:gsub(REF_PATTERN, function(idx_s, desc)
    local idx = tonumber(idx_s)
    local m = transcript_parts and transcript_parts[idx]
    if not m then
      print("[compact] REF 引用越界: " .. idx_s)
      return "[[REF:" .. idx_s .. "|" .. desc .. "]]"
    end
    return "[消息 " .. idx .. "] " .. desc
  end))
end

-- 折叠段归档（2026-08-10 硬盘利用）: compact_history 物理删除折叠段前，
-- 先 append 到 <history_path>.archive.jsonl（磁盘冷存储，内存零成本）。
-- 用途: ①可追溯——被折叠的原文永久保留，模型需要旧消息时可 read_file
-- 读归档（JSONL 逐行，grep 定位）；②修正旧注释"JSONL append-only 完整
-- 保留"的谎言——compact 后调用方 rebuild_history 用内存表重写文件，
-- 折叠段从主文件消失，此前是彻底丢失。
-- 限制: 磁盘满时静默跳过（compact 主流程不受影响，内存优先）；归档只
-- 增不减，超限由 /relocate 换盘或手动清理承担（用户明确"尽可能利用
-- 硬盘"）。
local function archive_folded(messages)
  if not messages or #messages == 0 then return end
  local f = io.open(history_path .. ".archive.jsonl", "a")
  if not f then return end
  for _, m in ipairs(messages) do
    local ok_w, werr = pcall(f.write, f, json.encode(m), "\n")
    if not ok_w then break end
  end
  f:close()
end
-- Compact（传统 opencode 自动压缩语义）: 折叠段消息**物理删除**——
-- （含 KEEP/REF 静态展开的原文，见下方 expand_keep_markers 调用点）已
-- 承载旧消息内容；折叠段不进请求体、对缓存无贡献，留在内存表纯占内存
-- （真机第二次 OOM 根因: 折叠不释放内存，93.6KB JSONL → 表 ~300KB
-- 驻留）。删除仅释放内存；**原文由 archive_folded 归档到
-- history.archive.jsonl（磁盘冷存储）承担可追溯**（旧注释称"JSONL
-- append-only 完整保留"与实际不符——compact 后 rebuild_history 用内存
-- 表重写主文件，折叠段会从主文件消失）。旧摘要消息被新摘要取代（锚定
-- 更新语义不变）。请求构造/估算的 folded 分支逻辑保留（无害兼容——
-- 折叠段已不存在，未来也不会再产生）。
local function compact_history(messages, config)
  if #messages <= COMPACT_KEEP + 1 then return nil end
  local keep = COMPACT_KEEP
  local est = 0
  for i = #messages, #messages - keep + 1, -1 do
    est = est + estimate_tokens(messages[i].content or "")
  end
  while keep < COMPACT_KEEP_MAX and est < COMPACT_KEEP_MIN_TOKENS
      and #messages - keep >= 1 do
    keep = keep + 1
    est = est + estimate_tokens(messages[#messages - keep + 1].content or "")
  end
  local previous_summary
  local old = {}
  for i = 1, #messages - keep do
    local m = messages[i]
    if m.role == "system" and type(m.content) == "string" then
      local s = m.content:match("^%[对话摘要%] (.*)$")
      if s then
        previous_summary = s
        -- drop the old summary message from the fold (it's passed separately)
      else
        old[#old + 1] = m
      end
    else
      old[#old + 1] = m
    end
  end
  local summary = summarize_history(old, config, previous_summary)
  if not summary then return nil end
  -- KEEP 标记展开（与 summarize 同源 transcript 序号）
  summary = expand_keep_markers(summary, build_transcript(old).parts)

  -- 折叠段**物理删除**（不标记、不驻留）: 旧摘要消息被新摘要取代直接
  -- 丢弃；其余折叠段内容已进摘要（KEEP/REF 展开），删除仅释放内存——
  -- 请求体本就是 [摘要 + 保留段]（folded 分支跳过），折叠段对缓存无
  -- 贡献，纯占内存。JSONL append-only 完整保留可追溯。
  -- 保留段首条不能是 role=tool（孤立 tool 消息缺陷，真机 gist 783a0f7
  -- 实证）: 若折叠边界恰落在 assistant(tool_calls) 与其 tool 结果之间，
  -- 保留段以孤立 tool 开头——OpenAI 规范要求 tool 消息必须对应前置
  -- assistant.tool_calls（部分端点直接 400，opencode.ai/zen 实测宽容
  -- 但这是请求合法性缺陷）。修复：首条是 tool 则向前多保留一条（其
  -- 前置 assistant），保证保留段以 user/assistant/system 开头。
  local first_keep = #messages - keep + 1
  while first_keep > 1 and messages[first_keep].role == "tool" do
    first_keep = first_keep - 1
  end
  -- 折叠段归档到磁盘（先于物理删除; old 含旧摘要以外的全部折叠消息。
  -- 磁盘满静默跳过——内存优先，compact 主流程不受影响）
  archive_folded(old)
  local result = {{role = "system", content = "[对话摘要] " .. summary}}
  for i = first_keep, #messages do
    result[#result + 1] = messages[i]
  end
  -- 就地替换（调用方持有同一表引用）
  for i = #messages, 1, -1 do messages[i] = nil end
  for i = 1, #result do messages[i] = result[i] end
  return messages
end

-- 压缩触发判定（tokens 上限阈值驱动，用户要求按 context_window 比例）:
--   估算 tokens ≥ 窗口 × COMPACT_WINDOW_RATIO → 压缩；条数 ≥
--   COMPACT_TRIGGER_COUNT 兜底（防海量小消息退化）。
-- window 缺省/为 0 时仅按条数。超限场景由 ensure_context_budget 的
-- 80% 窗口估算先行（压缩失败再 force_trim）。
local function should_compact(messages, window)
  if #messages <= COMPACT_KEEP + 1 then return false end
  if #messages >= COMPACT_TRIGGER_COUNT then return true end
  local w = tonumber(window) or 0
  if w <= 0 then return false end
  local est = 0
  for _, m in ipairs(messages) do
    if not m.folded then
      est = est + estimate_tokens(m.content or "")
          + estimate_tokens(m.tool_calls and tostring(m.tool_calls) or "")
      if est >= w * COMPACT_WINDOW_RATIO then return true end
    end
  end
  return false
end

-- Append-only session log: each line is one JSON-encoded message.
-- Append per message (O(new) memory) instead of rewriting the whole history
-- (O(n) each call, O(n^2) cumulative). load_history replays + trims.
-- 写盘失败警告（真机 2026-08-10 现场: 数据盘满 → io.open("a") 失败原本
-- 静默——新消息只进内存不进文件，且会话继续积累最终 encode OOM;
-- json.lua:98 table.concat 是 encode 峰值点）。首次失败打印一次，
-- disk_warned 防止刷屏。
local disk_warned = false
local function warn_disk(label)
  if disk_warned then return end
  disk_warned = true
  print("[disk] 警告: " .. label .. " 写盘失败（数据盘可能已满）——"
    .. "新消息仅存内存，重启后丢失；请清理磁盘或 /new 归档后重试")
end
local function append_history(msg)
  local f = io.open(history_path, "a")
  if not f then
    warn_disk("history")
    return
  end
  f:write(json.encode(msg), "\n")
  f:close()
end

-- Full rewrite of the session log (after compaction / new session / reset).
local function rebuild_history(messages)
  local f = io.open(history_path, "w")
  if not f then
    warn_disk("history")
    return
  end
  for _, m in ipairs(messages) do
    f:write(json.encode(m), "\n")
  end
  f:close()
end

-- 加载 history 到内存表（有界）。流式逐行读取——真机 2026-08-10 OOM
-- 根因修复: 旧实现 f:read("*a") 一次性读全文件再逐行 decode，峰值 =
-- 文件全文 + 解析表 + decode 中间态，数据盘满（history 巨大）时 2MB
-- 内存必爆；且 /debug 的 collect 也走 load_history → gist 提交失败。
-- 现改为逐行读: 峰值 = 单行 + 有界表（MAX_LOAD_HISTORY 条 + 字节预算），
-- 与文件总大小解耦。legacy 迁移路径保留全读（旧格式一次性迁移，量小）。
local function load_history()
  local fs = require("filesystem")
  if not fs.exists(history_path) then return {} end
  local f = io.open(history_path, "r")
  if not f then return {} end

  -- 首行探测格式（原逻辑只依赖 content 首字符 + 引号 role 键）
  local first_line = f:read("*l")
  if not first_line then f:close() return {} end
  local line0 = first_line:gsub("\r$", "")
  local is_json_lines = line0:sub(1, 1) == "{" and line0:find('"role"', 1, true) ~= nil

  if not is_json_lines then
    -- Legacy format (whole-table serialization): migrate once to JSON-line
    -- format. 一次性迁移（旧格式文件通常远小于 JSONL 积累），全读可接受。
    f:close()
    local f2 = io.open(history_path, "r")
    if not f2 then return {} end
    local content = f2:read("*a")
    f2:close()
    if content == "" then return {} end
    local ser = require("serialization")
    local ok, data = pcall(ser.unserialize, content)
    if ok and type(data) == "table" and (data[1] or data.role) then
      local list = data.role and {data} or data
      rebuild_history(list)  -- migrate
      return trim_history(list)
    end
    return {}
  end

  -- JSON-line format: 流式逐行，跳过损坏行。
  local messages = {}
  -- 条数上限（内存表有界）: 超过 MAX_LOAD_HISTORY 条丢更早的——真机
  -- 93.6KB JSONL 全量解析后表 ~300KB（OOM 根因之一）。文件本身
  -- append-only 完整保留（可追溯），只限内存表。
  local MAX_LOAD_HISTORY = math.floor(120 * MEM_SCALE2)
  local function ingest(line)
    local ok2, msg = pcall(json.decode, line)
    if ok2 and type(msg) == "table" and msg.role then
      if #messages == MAX_LOAD_HISTORY then
        table.remove(messages, 1)
      end
      messages[#messages + 1] = msg
    end
  end
  ingest(line0)
  for line in f:lines() do
    ingest(line:gsub("\r$", ""))
  end
  f:close()
  -- 字节上限: 解析后表裁剪到 mem_load_budget（可配，默认 100KB）。
  -- 配置经 pcall 读取（真机/测试均安全，缺失/损坏回退默认值）。
  local ok_cfg, cfg = pcall(config_mod.load)
  local load_budget = tonumber(ok_cfg and cfg and cfg.mem_load_budget) or 100000
  trim_to_bytes(messages, load_budget)

  -- 磁盘防护（真机 2026-08-10 现场: 数据盘满 + history 文件巨大）:
  -- append-only 文件跨会话无限累积（内存表每次只取 ≤120 条/100KB，
  -- 但文件本身只增不减），盘小（OC 数据盘通常 <1MB）时最终写满——
  -- 磁盘满又导致 append 静默失败 → 会话内存膨胀 → encode OOM
  -- （json.lua:98）。修复: 文件超过 mem_history_max_bytes（默认 256KB）
  -- 时自动 rebuild 截断到内存表规模（早段仅文件里有，内存表本就不
  -- 加载它们，截断不丢任何已加载内容；可追溯性由 /new 归档承担）。
  -- 文件大小用标准库 io.open+seek 获取（OpenOS filesystem 库无 size，
  -- 组件 getSize 需 proxy 解析；标准库最稳，测试环境也可用）。
  local history_size = 0
  local hf = io.open(history_path, "r")
  if hf then
    history_size = hf:seek("end") or 0
    hf:close()
  end
  local max_file = tonumber(ok_cfg and cfg and cfg.mem_history_max_bytes)
    or math.floor(256000 * MEM_SCALE2)
  if history_size > max_file then
    print("[disk] history 文件 " .. history_size .. "B 超过上限 " .. max_file
      .. "B，自动截断到当前内存表（" .. #messages .. " 条）...")
    rebuild_history(messages)
  end
  return trim_history(messages)
end

-- Redirect history storage (replaces the old agent_test HISTORY_PATH
-- rebinding hack). Tests call agent_test.set_history_path → this.
local function set_paths(p)
  history_path = p
end

-- 当前会话文件路径（/hist 显示会话名用）
local function current_path()
  return history_path
end

-- 会话列表（类 opencode /session）: 扫描目录下 *.jsonl 会话文件
--（/new 归档的 .txt 是归档而非会话，不列入）。dir 缺省用配置的
-- sessions 目录（测试可注入临时目录）。
-- 返回 {{name, count, modified}, ...} 按 modified 倒序。
local function list_sessions(dir)
  local fs = require("filesystem")
  local base = dir or sessions_dir
  -- pcall 兼容两环境: 真实 OC 对不存在路径抛错，测试 mock 返回空迭代器
  local ok_l, iter = pcall(fs.list, base)
  if not ok_l or type(iter) ~= "function" then return {} end
  local out = {}
  for name in iter do
    if name:sub(-6) == ".jsonl" then
      local path = base .. "/" .. name
      local count = 0
      local f = io.open(path, "r")
      if f then
        for _ in f:lines() do count = count + 1 end
        f:close()
      end
      local modified = 0
      local ok_m, m = pcall(fs.lastModified, path)
      if ok_m and m then modified = m end
      out[#out + 1] = {name = name:sub(1, -7), count = count, modified = modified}
    end
  end
  table.sort(out, function(a, b) return a.modified > b.modified end)
  return out
end

-- 运行时切换 sessions 目录（/relocate 迁移后立即生效；重启后由
-- config 的 data_dir 引导自动落到新盘）。
local function set_sessions_dir(p)
  sessions_dir = p
end

-- 当前 sessions 目录（disk 工具 list_storage 统计占用用）
local function get_sessions_dir()
  return sessions_dir
end

-- 磁盘清理（2026-08-10 新增，配合 /cleanup）: 删除非当前会话的旧
-- 会话文件（保留最近 keep 个，keep=0 仅保留当前）。当前会话按路径
-- 精确匹配（/session 切换后当前文件在 sessions 目录内）。返回
-- (删除数, 释放字节)。归档 .txt（/new 产物）不动——清理只针对
-- *.jsonl 会话文件；history 文件本体由 init.lua /cleanup 按
-- mem_history_max_bytes 截断。
local function cleanup_sessions(keep)
  local sessions = list_sessions()
  local current = current_path()
  local deleted, freed = 0, 0
  for i, s in ipairs(sessions) do
    if i > (keep or 0) then
      local path = sessions_dir .. "/" .. s.name .. ".jsonl"
      if path ~= current then
        local size = 0
        local f = io.open(path, "r")
        if f then
          size = f:seek("end") or 0
          f:close()
        end
        local ok_rm, res = pcall(os.remove, path)
        -- os.remove 成功返回 true（非 nil）；失败返回 nil + 错误信息。
        -- 曾误写 err==nil（成功时 err=true 恒不成立 → 永远删不掉，
        -- 2026-08-10 smoke 测试捕获）。
        if ok_rm and res == true then
          deleted = deleted + 1
          freed = freed + size
        end
      end
    end
  end
  return deleted, freed
end

-- Inject the chat client (agent.lua calls this after Section 5 defines
-- chat). Needed by summarize_history's LLM call.
local function set_chat(fn)
  injected_chat = fn
end

return {
  load_history = load_history,
  append_history = append_history,
  rebuild_history = rebuild_history,
  trim_history = trim_history,
  -- 物理字节裁剪（mem_pressure / load_history 上限共用，init.lua 引用）
  trim_to_bytes = trim_to_bytes,
  compact_history = compact_history,
  should_compact = should_compact,
  summarize_history = summarize_history,
  set_paths = set_paths,
  set_sessions_dir = set_sessions_dir,
  get_sessions_dir = get_sessions_dir,
  cleanup_sessions = cleanup_sessions,
  set_chat = set_chat,
  current_path = current_path,
  list_sessions = list_sessions,
  -- Exported because agent.lua's process_exchange still uses this constant.
  MAX_TOOL_RESULT = MAX_TOOL_RESULT,
  -- head+tail 每半预算（init.lua 截断用）
  TOOL_RESULT_KEEP = TOOL_RESULT_KEEP,
  -- 单一 token 估算实现（init.lua 引用，避免重复定义）
  estimate_tokens = estimate_tokens,
}
end

-- agent.agent.tools (embedded module)
package.preload["agent.tools"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.tools — tool registry for the OC Agent (Phase 1 plugin split).
--
-- Loads every tool module under this module's own tools/ directory
-- (src/agent/tools/*.lua) and registers its declarations. Each module
-- exports {tools = {<tool decls>}, exec = function(name, args, deps)}.
--
-- Self-bootstrapping extension point: an LLM can write a new module
-- into the tools/ directory via write_file; on the next start it is
-- auto-registered here (no agent.lua edit needed).
--
-- NOTE (plugin bootstrap): writing a custom tool module to tools/ works
-- in multi-file mode; the single-file build embeds modules via
-- package.preload and cannot require new files.
--
-- Directory enumeration falls back to the builtin module list when the
-- filesystem cannot be scanned (e.g. host-side test env without a real
-- filesystem). Both paths are exercised by the test harness.
-- ═══════════════════════════════════════════════════════════════

local fs = require("filesystem")

-- name → exec function (name, args, deps)
local REGISTRY = {}
-- name → raw declaration table ({type="function", ["function"]={...}})
local DECLS = {}
-- ordered declaration list returned by list()
local ORDER = {}

-- Builtin core tool modules, always loaded (canonical order).
local BUILTIN = {
  "agent.tools.file",
  "agent.tools.data",
  "agent.tools.component",
  "agent.tools.search",
  "agent.tools.shell",
  "agent.tools.subagent",
  "agent.tools.question",
  "agent.tools.compact",
}

-- Names already loaded by the BUILTIN loop (below). scan_dir skips these
-- so the directory scan does not re-require the six core modules.
-- This is a per-instance local table, NOT package.loaded: ocvm tests
-- clear package.loaded and re-require the registry fresh, giving the
-- reload semantics we want without double-loading builtins.
local loaded_names = {}

-- Resolve this module's own directory from the loader source, never cwd.
-- Prefer AGENT_DIR exported by init.lua (entry script — its source is an
-- absolute path under OpenOS). Fall back to debug.getinfo for direct
-- require scenarios where the source lacks the "@" prefix.
local base = AGENT_DIR
if not base or base == "" then
  local src = debug.getinfo(1, "S").source or ""
  base = src:match("^@(.*)[/\\][^/\\]+$")
end
if not base or base == "" then base = "." end
local TOOLS_DIR = base .. "/tools"

local function register(name, decl, exec)
  if type(name) ~= "string" or type(decl) ~= "table" or type(exec) ~= "function" then
    return
  end
  REGISTRY[name] = exec
  if not DECLS[name] then
    DECLS[name] = decl
    ORDER[#ORDER + 1] = decl
  end
end

local function register_module(mod)
  if type(mod) ~= "table" or type(mod.exec) ~= "function" then return end
  for _, decl in ipairs(mod.tools or {}) do
    local def = decl["function"]
    local tname = def and def.name
    if tname then register(tname, decl, mod.exec) end
  end
end

local function require_module(req_name)
  local ok, mod = pcall(require, req_name)
  if ok and type(mod) == "table" then
    register_module(mod)
    return true
  end
  print("[tools] warning: failed to load module " .. tostring(req_name)
    .. ": " .. tostring(mod))
  return false
end

-- Enumerate *.lua module names in a directory, as require names.
-- Returns an ordered list; {} when enumeration fails or finds nothing.
local function collect_dir_names(dir)
  local names = {}
  local ok, it = pcall(fs.list, dir)
  if not ok or type(it) ~= "function" then return names end
  local guard = 0
  for entry in it do
    guard = guard + 1
    if guard > 1000 then break end  -- safety against runaway iterators
    if type(entry) == "string" and entry:match("%.lua$") then
      names[#names + 1] = "agent.tools." .. entry:gsub("%.lua$", "")
    end
  end
  return names
end

-- Scan a tools directory and register every module found there.
-- `names_override` lets callers (e.g. tests) supply the module file
-- names (e.g. "hello.lua", as fs.list would return) without relying on
-- a real filesystem enumeration.
-- loaded_names (populated by the BUILTIN loop) is skipped here: the six
-- core modules were already required, so the directory scan only loads
-- genuinely new/custom modules. register() dedupes on name so ORDER
-- stays stable across rescans.
local function scan_dir(dir, names_override)
  local scanned = names_override or collect_dir_names(dir)
  for _, entry in ipairs(scanned) do
    -- accept file names ("hello.lua") or full require names
    local req_name = entry
    if type(entry) == "string" and entry:match("%.lua$") and not entry:match("^agent%.") then
      req_name = "agent.tools." .. entry:gsub("%.lua$", "")
    end
    if type(req_name) == "string" and not loaded_names[req_name] then
      require_module(req_name)
      loaded_names[req_name] = true
    end
  end
end

-- Core load: builtin modules first (deterministic), then any custom
-- modules discovered by the directory scan. Builtins are recorded in
-- loaded_names so scan_dir does not re-require them; register() still
-- dedupes on name so ORDER stays stable on re-scan/reload.
for _, req_name in ipairs(BUILTIN) do
  require_module(req_name)
  loaded_names[req_name] = true
end
scan_dir(TOOLS_DIR)

return {
  list = function() return ORDER end,
  register = register,
  register_module = register_module,
  registry = function() return REGISTRY end,
  scan_dir = scan_dir,
  tools_dir = TOOLS_DIR,
}
end

-- agent.agent.execute (embedded module)
package.preload["agent.execute"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.execute — tool execution dispatcher (Phase 1 plugin split).
--
-- Equivalent of the old Section 4 execute_tool body: parses the LLM's
-- (possibly sloppy) JSON arguments with the same salvage logic, then
-- dispatches to the registered tool implementation from agent.tools.
--
-- deps is injected by agent.lua's execute_tool wrapper: {json=...,
-- http_post=..., load_config=..., wait_modem_message=...,
-- subagent_listen_port=..., subagent_reply_port=...,
-- subagent_timeout=...}. Tool modules receive the same deps table.
-- ═══════════════════════════════════════════════════════════════

local tools = require("agent.tools")
local REGISTRY = tools.registry()

-- execute_lua was removed in a previous version; keep the old guard
-- message (run_tests asserts it) without any actual executor.
local EXECUTE_LUA_GUARD =
  "Error: execute_lua has been removed. Use json_query (JSON extraction), calc (math), or text_ops (string manipulation) instead."

local M = {}

function M.run(name, args_str, deps)
  deps = deps or {}
  local json = deps.json

  -- LLM-provided arguments can be sloppy JSON; never let decode errors kill us.
  local args
  local ok, decoded = pcall(json.decode, args_str or "{}")
  if ok and type(decoded) == "table" then
    args = decoded
  else
    -- Try to salvage: strip surrounding whitespace/quotes
    local cleaned = tostring(args_str or "{}"):gsub("^%s*", ""):gsub("%s*$", "")
    local ok2, decoded2 = pcall(json.decode, cleaned)
    if ok2 and type(decoded2) == "table" then
      args = decoded2
    else
      args = {}
    end
    -- Diagnose: expose raw args + error for debugging
    local err_info
    if ok and type(decoded) ~= "table" then
      -- decode actually succeeded, but the result wasn't an object —
      -- don't report it as a decode failure
      err_info = "decoded to " .. type(decoded) .. ", expected object"
    elseif ok then
      err_info = tostring(ok2 and decoded2 or decoded)
    else
      err_info = tostring(decoded)
    end
    return "Error parsing arguments (decode failed: " .. err_info .. "): " .. tostring(cleaned):sub(1, 200)
  end

  if name == "execute_lua" then
    return EXECUTE_LUA_GUARD
  end

  local exec = REGISTRY[name]
  if not exec then
    return "Unknown tool: " .. tostring(name)
  end

  local ok_run, result = pcall(exec, name, args, deps)
  if not ok_run then
    return "Error: " .. tostring(result)
  end
  return result
end

return M
end

-- agent.agent.chat (embedded module)
