-- ═══════════════════════════════════════════════════════════════
-- agent.subagent — subagent protocol support (Phase 3 split).
--
-- Verbatim move of the old agent.lua:
--   Section 3's SUBAGENT_* constants + wait_modem_message
--   Section 8's session family (session_path / load_session_history /
--   append_session_history / rebuild_session_history)
--
-- The old code referenced the WRITABLE_BASE local and the session
-- module's trim_history directly; here those come from agent.config
-- (writable_base) and agent.session (trim_history).
-- ═══════════════════════════════════════════════════════════════

local json = require("agent.json")
local fs = require("filesystem")
local config_mod = require("agent.config")
local session_mod = require("agent.session")

-- Subagent protocol constants (used by the subagent_call tool)
local SUBAGENT_LISTEN_PORT = 9090  -- subagent's task intake port
local SUBAGENT_REPLY_PORT = 9091   -- master's reply port
local SUBAGENT_TIMEOUT = 240       -- seconds to wait for a subagent reply
-- 文件服务端口（v0.3.84 新增，explorer 子代理读主代理硬盘）:
-- 主代理空闲时监听 FILE_PORT；explorer 子代理的 read_file/list_directory/
-- search_files/glob 通过 modem 代理到主代理执行，实现"内网读主代理文件"。
local FILE_PORT = 9092
local FILE_TIMEOUT = 60  -- 子代理等文件回复超时（主代理 chat 中时排队）

-- 文件代理: 子代理 explorer 用它把文件工具转发到主代理执行。
-- exec 签名与本地工具一致 (name, args, deps)。返回与本地工具同格式
-- （read_file → 文件内容字符串; 错误 → "Error: ..."）。
local function file_proxy(name, args, deps, master_addr)
  local ok_m, modem = pcall(function()
    local comp = require("component")
    return comp.modem
  end)
  if not ok_m or not modem then return "Error: file proxy: no modem component" end
  local req = {v = 1, op = name}
  if type(args) == "table" then
    for k, v in pairs(args) do req[k] = v end
  end
  local ok_open = pcall(modem.open, FILE_PORT)
  local ok_send = pcall(modem.send, master_addr, FILE_PORT, deps.json.encode(req))
  if not ok_send then return "Error: file proxy: send failed" end
  local sender, port, payload = deps.wait_modem_message(FILE_TIMEOUT, FILE_PORT)
  if not sender then return "Error: file proxy: no reply from master within " .. FILE_TIMEOUT .. "s" end
  local ok_d, reply = pcall(deps.json.decode, payload)
  if not ok_d or type(reply) ~= "table" then return "Error: file proxy: bad reply" end
  if reply.ok then
    return reply.content or ""
  end
  return "Error: " .. tostring(reply.error or "unknown")
end

-- 处理单条 modem 文件请求（推模式，TUI readInput 事件回调用）。
-- exec_fn 由 init.lua 注入（execute_tool 包装），签名 exec_fn(name, args_table)
-- 返回 (ok, result_string)。
local function handle_file_message(exec_fn, sender, port, payload)
  local ok_c, comp = pcall(require, "component")
  if not ok_c or not comp.modem then return false end
  local modem = comp.modem
  local json = require("agent.json")
  if port ~= FILE_PORT or type(payload) ~= "string" then return false end
  local ok_j, req = pcall(json.decode, payload)
  local reply
  if not ok_j or type(req) ~= "table" or not req.op then
    reply = json.encode({v = 1, ok = false, error = "bad file request"})
  else
    local op = req.op:match("^file:(.+)$") or req.op
    -- 只服务只读文件工具（安全边界: 文件服务绝不执行写工具）
    if op == "read_file" or op == "list_directory"
        or op == "search_files" or op == "glob" then
      local args = {}
      for k, v in pairs(req) do
        if k ~= "v" and k ~= "op" then args[k] = v end
      end
      local ok_exec, result = exec_fn(op, args)
      if ok_exec and type(result) == "string" then
        reply = json.encode({v = 1, ok = true, content = result})
      else
        reply = json.encode({v = 1, ok = false, error = tostring(result)})
      end
    else
      reply = json.encode({v = 1, ok = false, error = "op not allowed: " .. tostring(op)})
    end
  end
  pcall(modem.send, sender, FILE_PORT, reply)
  return true
end

-- 主代理侧文件服务: 非阻塞处理所有 pending 文件请求（event.pull 0s 轮询，
-- 在 REPL/TUI 空闲时调用；chat 阻塞期间请求排队，恢复空闲后处理）。
local function serve_file_requests(exec_fn)
  local ok_e, event = pcall(require, "event")
  local ok_c, comp = pcall(require, "component")
  if not ok_e or not ok_c or not comp.modem then return end
  while true do
    local sig = {event.pull(0, "modem_message")}
    if not sig[1] then break end
    handle_file_message(exec_fn, sig[3], sig[4], sig[6])
  end
end

-- Wait for a modem_message event (with timeout). Returns
-- (sender, port, arg1) or nil on timeout. Uses event.pull which yields.
-- on_other（v0.3.85）: 非 reply_port 的 modem 消息转发给回调（完整 sig
-- 表）——主代理 subagent_call 等待回复期间，explorer 子代理的文件服务
-- 请求经它处理。不转发就丢弃（event.pull 消费即失），形成死锁: 子代理
-- 等文件回复 60s，主代理等任务回复 240s，互相等待直到超时（真机 gist
-- 现场: explorer 子代理执行 list_directory/read_file 卡 thinking）。
-- v0.3.86: interrupted 事件（Ctrl+C）设中断标志提前返回——返回 nil
-- 前清除标志; 调用方（subagent_call）把 nil + 中断转成 "interrupted"
-- 错误，用户可 Ctrl+C 终止 subagent_call 等待。
local function wait_modem_message(timeout, reply_port, on_other)
  local event = require("event")
  local interrupt = require("agent.interrupt")
  local waited = 0
  local step = 0.5
  while timeout == nil or waited < timeout do
    -- 无过滤 pull + 自判事件名（v0.3.89 修复）: OpenOS event.pull 的
    -- 多过滤语义是"事件名 match 参数1 且 参数N 匹配事件第 N 参数"（AND
    -- 位置匹配），不是匹配多个事件名——("modem_message","interrupted")
    -- 要求事件名含 modem_message 且参数1=="interrupted"，interrupted
    -- 事件（{"interrupted", <time>}）永远被拒，Ctrl+C 在此失效
    -- （probe_pullmulti 实证）。改无过滤 pull，非目标事件忽略重拉。
    local sig = {event.pull(step)}
    if sig[1] == "modem_message" then
      local sender = sig[3]
      local port = sig[4]
      -- sig[2] is receiver address, sig[3] sender, sig[4] port
      if reply_port == nil or port == reply_port then
        return sender, port, sig[6]
      end
      if on_other then
        on_other(sig)
      end
    elseif sig[1] == "interrupted" then
      interrupt.set()
      return nil
    end
    waited = waited + step
  end
  return nil
end

-- Subagent sessions: each subagent keeps per-session append-only histories
-- on its own disk (<writable>/subagent_sessions/<session>/history.jsonl).
-- Reusing the same session id continues the conversation; omitting it
-- starts fresh.

local function session_path(session)
  local safe = tostring(session):gsub("[^%w_%-]", "_"):sub(1, 64)
  return config_mod.writable_base .. "/subagent_sessions/" .. safe .. "/history.jsonl"
end

-- Load session history (JSONL lines, same format as main history).
local function load_session_history(session)
  local p = session_path(session)
  local fs = require("filesystem")
  if not fs.exists(p) then return {} end
  local f = io.open(p, "r")
  if not f then return {} end
  local content = f:read("*a")
  f:close()
  local messages = {}
  for line in content:gmatch("[^\r\n]+") do
    local ok2, msg = pcall(json.decode, line)
    if ok2 and type(msg) == "table" and msg.role then
      messages[#messages + 1] = msg
    end
  end
  return session_mod.trim_history(messages)
end

-- Append one message to a session history.
local function append_session_history(session, msg)
  local p = session_path(session)
  local fs = require("filesystem")
  local dir = p:match("^(.*)/[^/]+$")
  if dir then pcall(fs.makeDirectory, dir) end
  local f = io.open(p, "a")
  if not f then return end
  f:write(json.encode(msg), "\n")
  f:close()
end

-- Rebuild a session history (after compaction/trim).
local function rebuild_session_history(session, messages)
  local p = session_path(session)
  local fs = require("filesystem")
  local dir = p:match("^(.*)/[^/]+$")
  if dir then pcall(fs.makeDirectory, dir) end
  local f = io.open(p, "w")
  if not f then return end
  for _, m in ipairs(messages) do
    f:write(json.encode(m), "\n")
  end
  f:close()
end

return {
  wait_modem_message = wait_modem_message,
  session_path = session_path,
  load_session_history = load_session_history,
  append_session_history = append_session_history,
  rebuild_session_history = rebuild_session_history,
  file_proxy = file_proxy,
  serve_file_requests = serve_file_requests,
  handle_file_message = handle_file_message,
  SUBAGENT_LISTEN_PORT = SUBAGENT_LISTEN_PORT,
  SUBAGENT_REPLY_PORT = SUBAGENT_REPLY_PORT,
  SUBAGENT_TIMEOUT = SUBAGENT_TIMEOUT,
  FILE_PORT = FILE_PORT,
  FILE_TIMEOUT = FILE_TIMEOUT,
}
end

-- agent.agent.interrupt (embedded module)
package.preload["agent.interrupt"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.interrupt — Ctrl+C 中断支持（v0.3.86）
--
-- 痛点: 非 Ready 状态（chat 请求 / 工具执行 / 重试退避 / subagent
-- 等待）时 Ctrl+C 无效——OpenOS 的 os.sleep 内部 event.pull("timer")
-- 带过滤，interrupted 事件不匹配被丢弃; http 读循环 / wait_modem_message
-- 同理。事件到不了处理代码。
--
-- 方案: 可中断 os.sleep 补丁——无过滤轮询改为多过滤 pull
-- ("timer","interrupted","modem_message")，interrupted 匹配时设置标志
-- 提前返回; modem_message 转发给注册 handler（文件服务——chat 期间
-- explorer 请求实时处理，不排队不丢）。所有阻塞点 yield 后检查标志。
--
-- 阻塞点接入清单:
--   http.lua     读循环每 chunk + 重试退避（yield 后检查 interrupt.poll）
--   subagent.lua wait_modem_message 多过滤 + interrupted 检测
--   init.lua     process_exchange 工具循环 + chat 错误处理
-- ═══════════════════════════════════════════════════════════════

local event = require("event")
local computer = require("computer")

local FLAG = false

local M = {}

M.set = function() FLAG = true end
M.clear = function() FLAG = false end
M.poll = function() return FLAG end

-- 消费式读取: 返回并清除标志（process_exchange 每轮工具循环用）
M.consume = function()
  local v = FLAG
  FLAG = false
  return v
end

-- 注册: sleep 期间收到的 modem_message 转发（main() 注入文件服务 hook）
M.forward = nil

M.installed = false

-- 可中断 os.sleep 补丁（替换 OpenOS 原版）。幂等。
-- 原版内部 event.pull("timer") 单过滤——Ctrl+C 的 interrupted 被丢弃。
-- 多过滤 ("timer","interrupted","modem_message"): interrupted 设标志
-- 提前返回（调用方检测 poll 终止阻塞）; modem_message 转发 handler
-- （文件服务）; timer 忽略（agent 不用 event.timer）。其他事件（key_down
-- 等）仍被丢弃——chat 期间本就不应接受输入，语义合理。
M.install = function()
  if M.installed then return end
  os.sleep = function(t)
    -- 基准用 computer.uptime()（v0.3.88 热修复）: os.clock() 在 OC/ocvm
    -- 是 CPU 时间——空闲不前进，os.sleep(t>0) 的 deadline 永不达到 →
    -- while true 死循环挂起（probe_interrupt3 实证: os.sleep(2) 挂死,
    -- probe_clock 实证: sleep 2s clock 只走 0.024s）。uptime 是墙钟。
    local deadline = computer.uptime() + (t or 0)
    while true do
      -- 先拉事件再检查超时（v0.3.87 修复）: OpenOS internet.request
      -- 迭代器等待数据时调 os.sleep(0)（yield 让出）——原实现先检查
      -- remaining<=0 直接 return，t=0 时从不 event.pull，Ctrl+C 的
      -- interrupted 永远收不到（probe_interrupt 实证: 等待期注入
      -- interrupted 补丁未触发）。改为先 pull(0)（非阻塞让出 + 消费
      -- pending 事件）再检查超时，os.sleep(0) 也能捕获中断。
      local remaining = deadline - computer.uptime()
      local wait = remaining > 0 and math.min(0.1, remaining) or 0
      -- 无过滤 pull + 自判事件名（v0.3.89 修复）: OpenOS 的
      -- event.pull(wait, "a","b","c") 语义是"事件名 match 'a' 且 参数1
      -- =='b' 且 参数2=='c'"（AND 位置匹配），不是匹配多个事件名——
      -- 多过滤用法下 interrupted 事件永远被拒（probe_pullmulti 实证:
      -- 单过滤/无过滤都能收到 interrupted，多过滤 nil）。改用无过滤
      -- pull，非目标事件忽略继续循环。
      local sig = {event.pull(wait)}
      if sig[1] == "interrupted" then
        FLAG = true
        return
      elseif sig[1] == "modem_message" then
        local h = M.forward
        if h then pcall(h, sig) end
      end
      -- 其他事件: 忽略继续循环; 超时（sig[1]==nil）由 remaining 兜底
      if remaining <= 0 then return end
    end
  end
  M.installed = true
end

return M
end

-- agent.agent.selftest (embedded module)
package.preload["agent.selftest"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.selftest — 实机自检（/selftest 命令）
--
-- 为什么存在: ocvm 层验证的是"模拟器行为"（4MB RAM、C++ 模拟的
-- internet/时钟），模拟层（run_tests）验证的是"代码路径"（mock
-- 硬编码响应）。真机（OpenComputers JVM + luajit + 2MB RAM + 真实
-- 网络）的行为两者都覆盖不到——os.clock CPU 时间、event.pull 多过滤
-- 语义、迭代器让出、JVM internet 时序，都是模拟层假阴性、ocvm 偶发
-- 假阴性的点。本模块嵌入式自检: agent.lua 已在真机（用户日常运行），
-- 零传输（无需上传脚本），/selftest 一键跑完写结果文件 + 可选 gist
-- 回传（复用 agent.debug.upload）。
--
-- 内存约束: 真机 2MB。每个测试独立 pcall + 每测 collectgarbage，
-- 大字符串（报告）最后才组装。
--
-- 测试项（真机能力设计）:
--   env    环境 sanity（OS/uptime/RAM/CPU/挂载盘）——验证环境识别
--   json   JSON roundtrip（空表/嵌套/转义边界）——真实 luajit 行为
--   fs     文件系统读写追加删除——真实 OpenOS 文件系统
--   session session 文件持久化 roundtrip
--   config config 存/取 roundtrip
--   net    真实 internet 小请求（GET api.github.com）——真实网络 +
--          http.lua 超时/重试链路（含 connection 挂起保护）
--   interrupt interrupt 补丁: install + timer 注入 + os.sleep 提前返回
--          （真机 JVM 事件时序——ocvm 已验证，真机最宝贵）
--   tools  TOOLS 清单（19 项齐全）
--   mem    内存预算 sanity（collectgarbage("count") vs 2MB）——GC 健康
-- ═══════════════════════════════════════════════════════════════

local M = {}

-- 结果收集（最后才拼大字符串; 中间只存小行）
local results = {}
local started = os.clock()

local function record(name, ok, detail)
  -- 同名覆盖（v0.3.91）: 线程超时放弃后线程可能仍在后台跑，迟到写入
  -- 会重复——按 name 覆盖，最终保留最后一次结果。
  for i, r in ipairs(results) do
    if r.name == name then
      results[i] = { name = name, ok = ok, detail = detail or "" }
      collectgarbage("collect")
      return
    end
  end
  results[#results + 1] = {
    name = name,
    ok = ok,
    detail = detail or "",
  }
  collectgarbage("collect")  -- 每测 gc（2MB 约束）
end

-- 所有测试经 pcall 包裹——单个崩溃不中断后续。
-- 成功路径: 测试函数内部自行 record（各函数只 record 一次）；
-- 崩溃路径: 这里兜底 record（防止"崩溃后无记录"）。
-- 线程化 + 超时（v0.3.91）: OC internet.request 连接阶段无超时
-- （v0.3.73 /debug 卡死教训: 连接挂起时 Lua 层不运行，Ctrl+C 补丁
-- 也无机会）——同步跑 net 测试会把整个 selftest 卡死只能重启。每项
-- 测试跑在 thread 里 + waitForAll(timeout) 超时 → 超时记 FAIL 继续
-- 下一项，任何一项卡住不影响整体。thread 不可用（测试/精简环境）
-- 回退同步执行。
local function run_test(name, fn, timeout_sec)
  local ok_th, thread = pcall(require, "thread")
  timeout_sec = timeout_sec or 30
  if not ok_th or not thread or not thread.create or not thread.waitForAll then
    local ok, err = pcall(fn)
    if not ok then
      record(name, false, "CRASH: " .. tostring(err))
    end
    return
  end
  local t = thread.create(fn)
  local ok_w, werr = pcall(thread.waitForAll, {t}, timeout_sec)
  if not ok_w or not werr then
    record(name, false, "TIMEOUT after " .. timeout_sec .. "s (线程卡住已放弃)")
  end
end

-- ════════════════════════════════════════
-- 1. env — 环境 sanity
-- ════════════════════════════════════════
local function test_env()
  local ok_c, computer = pcall(require, "computer")
  if not ok_c then record("env", false, "no computer lib: " .. tostring(computer)); return end
  local info = {}
  local ok_g, g = pcall(computer.getDeviceInfo)
  if ok_g and type(g) == "table" then
    for k, v in pairs(g) do
      if type(v) == "table" and v.description then
        info[#info + 1] = tostring(v.description)
      end
    end
  end
  local free, total = pcall(computer.freeMemory)
  local _, total_mem = pcall(computer.totalMemory)
  record("env", true,
    "uptime=" .. string.format("%.0f", computer.uptime())
    .. " free=" .. tostring(free) .. " total=" .. tostring(total_mem)
    .. " devices=" .. table.concat(info, "|"))
end

-- ════════════════════════════════════════
-- 2. json — roundtrip 边界（真实 luajit 行为）
-- ════════════════════════════════════════
local function test_json()
  local ok_j, json = pcall(require, "agent.json")
  if not ok_j then record("json", false, "no agent.json: " .. tostring(json)); return end
  -- 空表 encode（OC json.lua 历史: {} → [] 数组编码——真机行为验证）
  local ok1, e1 = pcall(json.encode, {})
  local d1 = ok1 and e1 or ("ERR: " .. tostring(e1))
  -- 嵌套 roundtrip
  local ok2, e2 = pcall(json.encode, {a = {b = {c = 1}}, d = "x\ny", e = true, f = nil})
  local r2 = "n/a"
  if ok2 then
    local ok3, d3 = pcall(json.decode, e2)
    r2 = ok3 and (tostring(d3 and d3.a and d3.a.b and d3.a.b.c)) or ("DECODE_ERR: " .. tostring(d3))
  else
    r2 = "ENCODE_ERR: " .. tostring(e2)
  end
  local ok4, e4 = pcall(json.encode, {n = 123456789012345})
  record("json", ok2 and ok4,
    "empty={}->" .. tostring(d1) .. " nested.c=" .. tostring(r2)
    .. " bigint=" .. tostring(ok4 and e4 or ("ERR: " .. tostring(e4))))
end

-- ════════════════════════════════════════
-- 3. fs — 文件系统读写（真实 OpenOS）
-- ════════════════════════════════════════
local function test_fs()
  local ok_cfg, cfg = pcall(require, "agent.config")
  if not ok_cfg or not cfg or not cfg.writable_base then
    record("fs", false, "no agent.config: " .. tostring(cfg)); return
  end
  local p = cfg.writable_base .. "/selftest_tmp.txt"
  local ok_w = pcall(function()
    local f = io.open(p, "w")
    f:write("SELFTEST_FS_12345\n")
    f:close()
  end)
  local readback = nil
  local ok_r = pcall(function()
    local f = io.open(p, "r")
    readback = f:read("*a")
    f:close()
  end)
  -- 追加
  local ok_a = pcall(function()
    local f = io.open(p, "a")
    f:write("APPEND_67890\n")
    f:close()
  end)
  -- 追加后重读（验证 append 真实生效）
  local readback2 = nil
  local ok_r2 = pcall(function()
    local f = io.open(p, "r")
    readback2 = f:read("*a")
    f:close()
  end)
  -- 清理
  pcall(os.remove, p)
  record("fs", ok_w and ok_r and ok_a and ok_r2
    and readback == "SELFTEST_FS_12345\n"
    and readback2 == "SELFTEST_FS_12345\nAPPEND_67890\n",
    "write=" .. tostring(ok_w) .. " read=" .. tostring(ok_r)
    .. " append=" .. tostring(ok_a) .. " r2=" .. tostring(ok_r2)
    .. " got=" .. tostring(readback2):gsub("\n", "\\n"))
end

-- ════════════════════════════════════════
-- 4. session — 会话文件持久化 roundtrip
--    （agent.session 基于"当前路径"（set_paths/set_sessions_dir 设置），
--     append_history(msg)/load_history() 无 per-path 变参——测试借
--     set_sessions_dir 指向临时目录，跑完恢复。改路径会改变 agent 的
--     会话文件位置——只在测试期改，结束后恢复原值。）
-- ════════════════════════════════════════
local function test_session()
  local ok_s, session = pcall(require, "agent.session")
  if not ok_s then record("session", false, "no agent.session: " .. tostring(session)); return end
  local ok_cfg, cfg = pcall(require, "agent.config")
  if not ok_cfg or not cfg or not cfg.writable_base then
    record("session", false, "no config"); return
  end
  local orig_dir = session.get_sessions_dir and session.get_sessions_dir()
  local tmp_dir = cfg.writable_base .. "/selftest_sess"
  pcall(session.set_sessions_dir, tmp_dir)
  -- 清残留（tmp_dir 下的 session 文件）
  pcall(function()
    local ok_fs, fs = pcall(require, "filesystem")
    if ok_fs and fs then
      for item in fs.list(tmp_dir) do
        pcall(os.remove, tmp_dir .. "/" .. item)
      end
    end
  end)
  -- 追加两条 + 重读
  local ok_a1 = pcall(session.append_history, {role = "user", content = "FIRST_LINE"})
  local ok_a2 = pcall(session.append_history, {role = "user", content = "SECOND_LINE"})
  local lines = nil
  local ok_l = pcall(function()
    lines = session.load_history()
  end)
  -- 恢复原会话目录
  if orig_dir then pcall(session.set_sessions_dir, orig_dir) end
  -- 判定: load 回 2 条（content 匹配）
  local content_match = ok_l and type(lines) == "table" and #lines >= 2
  if content_match then
    content_match = false
    local found1, found2 = false, false
    for _, m in ipairs(lines) do
      if m and m.content == "FIRST_LINE" then found1 = true end
      if m and m.content == "SECOND_LINE" then found2 = true end
    end
    content_match = found1 and found2
  end
  record("session", ok_a1 and ok_a2 and content_match,
    "append=" .. tostring(ok_a1) .. "/" .. tostring(ok_a2)
    .. " load=" .. tostring(ok_l) .. " n=" .. tostring(type(lines) == "table" and #lines or "?"))
end

-- ════════════════════════════════════════
-- 5. config — 存/取 roundtrip
-- ════════════════════════════════════════
local function test_config()
  local ok_cfg, cfg = pcall(require, "agent.config")
  if not ok_cfg or not cfg then record("config", false, "no agent.config: " .. tostring(cfg)); return end
  local ok_l, loaded = pcall(cfg.load)
  if not ok_l then record("config", false, "load crash: " .. tostring(loaded)); return end
  -- 存在性 + 类型 sanity（不写回——不动用户配置）
  local t = type(loaded)
  local has_api = type(loaded) == "table" and loaded.api_key ~= nil
  record("config", ok_l and (type(loaded) == "table"),
    "type=" .. tostring(t) .. " has_api_key=" .. tostring(has_api))
end

-- ════════════════════════════════════════
-- 6. net — 真实 internet 小请求（GET，验证网络 + http 超时链路）
-- ════════════════════════════════════════
local function test_net()
  local ok_h, http = pcall(require, "agent.http")
  if not ok_h then record("net", false, "no agent.http: " .. tostring(http)); return end
  -- 短超时配置（测试不长时间挂起; http.lua 的 120s 读超时对自检太久）
  -- http.post 用默认 retry_budget; GET 走 internet.request 原始 API
  local ok_i, internet = pcall(require, "internet")
  if not ok_i then record("net", false, "no internet lib: " .. tostring(internet)); return end
  local ok_c, computer = pcall(require, "computer")
  local timeout = 20  -- 秒（自检用短超时）
  local handle = nil
  local ok_open = pcall(function()
    handle = internet.request("https://api.github.com/zen", nil, {["User-Agent"] = "oc-agent-selftest"})
  end)
  if not ok_open or not handle then
    record("net", false, "connect fail: " .. tostring(handle)); return
  end
  -- 迭代读取（带 deadline——http.lua 同款挂起保护）
  local chunks = {}
  local deadline = (ok_c and computer.uptime() or os.clock()) + timeout
  local now_fn = ok_c and computer.uptime or os.clock
  local ok_iter = true
  local iter_err = nil
  for chunk in handle do
    chunks[#chunks + 1] = chunk
    if now_fn() > deadline then
      iter_err = "read timeout after " .. timeout .. "s"
      break
    end
  end
  local body = table.concat(chunks)
  -- 验证: 返回非空（api.github.com/zen 返回一句话）
  record("net", body ~= nil and #body > 0,
    "body_len=" .. tostring(#body) .. " head=" .. tostring(body):sub(1, 40)
    .. (iter_err and (" iter_err=" .. tostring(iter_err)) or ""))
end

-- ════════════════════════════════════════
-- 7. interrupt — 补丁 + timer 注入 + 提前返回
--    （真机 JVM 事件时序——ocvm 已验证，真机最宝贵）
-- ════════════════════════════════════════
local function test_interrupt()
  local ok_i, interrupt = pcall(require, "agent.interrupt")
  if not ok_i then record("interrupt", false, "no agent.interrupt: " .. tostring(interrupt)); return end
  local ok_c, computer = pcall(require, "computer")
  local ok_e, event = pcall(require, "event")
  if not (ok_c and ok_e) then record("interrupt", false, "computer/event missing"); return end
  interrupt.install()
  local up0 = computer.uptime()
  local timer_id = event.timer(0.5, function()
    computer.pushSignal("interrupted")
  end)
  local t0 = os.clock()
  os.sleep(2)  -- 应被 0.5s 的 interrupted 提前打断
  local dt = os.clock() - t0
  local flag = interrupt.poll()
  interrupt.clear()
  pcall(event.cancel, timer_id)
  -- 判定: flag 已置（事件链路通）且返回快（提前打断）或至少 flag 置位
  record("interrupt", flag and dt < 1.5,
    "flag=" .. tostring(flag) .. " dt=" .. string.format("%.2f", dt)
    .. " (expect <1.5 if early-return, ~2 if full wait)")
end

-- ════════════════════════════════════════
-- 8. tools — TOOLS 清单齐全（19 项）
-- ════════════════════════════════════════
local function test_tools()
  local ok_t, tools = pcall(require, "agent.tools")
  if not ok_t then record("tools", false, "no agent.tools: " .. tostring(tools)); return end
  local ok_l, list = pcall(tools.list)
  if not ok_l or type(list) ~= "table" then record("tools", false, "list fail"); return end
  local names = {}
  for _, t in ipairs(list) do
    local n = t and t["function"] and t["function"].name
    if n then names[#names + 1] = n end
  end
  local EXPECTED = {
    "read_file","edit_file","append_file","write_file","list_directory",
    "search_files","glob","json_query","calc","text_ops",
    "component_list","component_doc","component_invoke",
    "web_search","shell_execute","subagent_call","subagent_discover",
    "ask_user","compact_history",
  }
  local missing = {}
  for _, e in ipairs(EXPECTED) do
    local found = false
    for _, n in ipairs(names) do if n == e then found = true break end end
    if not found then missing[#missing + 1] = e end
  end
  record("tools", #missing == 0 and #names == 19,
    "count=" .. #names .. " missing=" .. (#missing > 0 and table.concat(missing, ",") or "none"))
end

-- ════════════════════════════════════════
-- 9. mem — 内存预算 sanity（2MB 真机约束）
-- ════════════════════════════════════════
local function test_mem()
  local ok_c, computer = pcall(require, "computer")
  if not ok_c then record("mem", false, "no computer lib"); return end
  collectgarbage("collect")
  local ok_f, free = pcall(computer.freeMemory)
  local ok_t, total = pcall(computer.totalMemory)
  local used = (ok_t and total or 0) - (ok_f and free or 0)
  local pct = used / math.max(1, total or 1) * 100
  -- 真机 2MB: 占用 >85% 视为危险（agent 常驻 + 系统）
  record("mem", ok_f and ok_t and pct < 85,
    string.format("free=%.0f used=%.0f total=%.0f (%.0f%%)", free or 0, used, total or 0, pct))
end

-- ════════════════════════════════════════
-- 执行器
-- ════════════════════════════════════════
M.run = function()
  results = {}
  -- 每项超时（线程化，v0.3.91）: 单项卡住（如 net 连接挂起）30s 自动
  -- FAIL 继续，不再需要重启。interrupt 项含 os.sleep(2) 预期耗时，给
  -- 15s 裕量。
  run_test("env", test_env, 15)
  run_test("json", test_json, 15)
  run_test("fs", test_fs, 15)
  run_test("session", test_session, 15)
  run_test("config", test_config, 15)
  run_test("net", test_net, 30)
  run_test("interrupt", test_interrupt, 15)
  run_test("tools", test_tools, 15)
  run_test("mem", test_mem, 15)
  -- 组装报告（最后才拼大字符串）
  local lines = {
    "OC Agent selftest — " .. os.date("%Y-%m-%d %H:%M"),
    "elapsed " .. string.format("%.1fs", os.clock() - started),
  }
  local pass = 0
  for _, r in ipairs(results) do
    if r.ok then pass = pass + 1 end
    lines[#lines + 1] = (r.ok and "PASS" or "FAIL") .. " " .. r.name
      .. (r.detail ~= "" and (" — " .. r.detail) or "")
  end
  lines[#lines + 1] = "RESULT: " .. pass .. "/" .. #results .. " pass"
  return table.concat(lines, "\n")
end

return M
end

-- agent.agent.debug (embedded module)
package.preload["agent.debug"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.debug — 诊断报告收集 + 上传（Phase 4b 新增）。
--
-- 供 `/debug` 命令使用：把版本、配置（脱敏）、最近会话历史、
-- 运行状态汇总成一个文本报告，可选上传到 GitHub Gist
-- （api.github.com/gists），便于远程调试。
--
-- 依赖: agent.json / agent.http / agent.config（config 传参即可）。
-- ═══════════════════════════════════════════════════════════════

local json = require("agent.json")

-- 脱敏: token 类完全遮蔽；key 类保留首 4 + 尾 4
local function mask(s)
  if not s or s == "" then return "(未设置)" end
  if #s <= 8 then return "***" end
  return s:sub(1, 4) .. "***" .. s:sub(-4)
end
local function mask_token(s)
  if not s or s == "" then return "(未设置)" end
  return "(已设置 " .. #s .. " 字符)"
end

-- ── 历史消息脱敏（2026-08-09 安全修复）──
-- 泄漏背景: GitHub 扫描到 gist 内的完整 PAT（oc-agent-debug note）并撤销。
-- Config 段一直安全（gist_token 完全遮蔽），泄漏点在 Recent history 段：
-- msg_line 原样输出消息 content——若历史中某条消息（用户自然语言提交的
-- token、或工具结果如 read_file config.json 输出）含明文密钥，报告即带出。
-- 修复: 已知明文值（config 中的 api_key/tavily_key/gist_token）整体替换
-- + 常见 token 格式模式遮蔽（GitHub PAT/OAuth/OpenAI/Tavily 前缀）。

-- 收集 config 中已知的敏感明文值（去重、跳过空值/过短值）
local function known_secrets(config)
  local list = {}
  local seen = {}
  local cfg = config or {}
  for _, k in ipairs({ "api_key", "tavily_key", "gist_token" }) do
    local v = cfg[k]
    if type(v) == "string" and #v >= 8 and not seen[v] then
      seen[v] = true
      list[#list + 1] = v
    end
  end
  return list
end

-- 纯文本替换（避免 Lua pattern magic 字符误伤：token 值含 % . - 等时
-- string.gsub 会把第一个参数当 pattern——已知值必须按字面匹配）
local function plain_replace(s, find_str, repl)
  local out = s
  local pos = 1
  while true do
    local a, b = string.find(out, find_str, pos, true)
    if not a then break end
    out = out:sub(1, a - 1) .. repl .. out:sub(b + 1)
    pos = a + #repl
  end
  return out
end

-- token 前缀（格式遮蔽：保留前缀便于人读，值部分一律 ***）。
-- 长的前缀在前（github_pat_ 先于 ghp_ 检查；sk-ant- 先于 sk-）。
-- 实现用词元扫描 + 函数替换：一次 gsub 完成，无二次匹配问题
-- （Lua pattern 的 ? 量词在本环境 5.4.6 上行为异常，且分组+量词
--   二次匹配污染产物——实测 a(b)?c 匹配 abc 返回 nil，弃用）。
local TOKEN_PREFIXES = {
  "github_pat_", "ghp_", "gho_", "ghu_", "ghs_", "ghr_",
  "sk-ant-", "sk-", "tvly-",
}

-- 对文本做脱敏：先替换已知明文值，再按前缀格式遮蔽 token 值。
-- 顺序很重要：已知值替换优先（更长更精确，避免模式先行后值已变）。
local function redact(text, config)
  if not text or text == "" then return text end
  local out = tostring(text)
  for _, secret in ipairs(known_secrets(config)) do
    out = plain_replace(out, secret, "***")
  end
  -- 词元扫描: 对每个 [%w_]（含 - 的连续 token 候选）检查前缀，
  -- 命中则保留前缀、值部分换 ***；函数替换单遍完成，无二次匹配。
  out = out:gsub("[%w_%-]+", function(tok)
    for _, prefix in ipairs(TOKEN_PREFIXES) do
      if tok:sub(1, #prefix) == prefix then
        return prefix .. "***"
      end
    end
    return tok
  end)
  return out
end

-- 单条消息 → 紧凑单行（tool 结果截断放宽到 1000 字符；
-- content 先经 redact 脱敏——历史中可能含明文密钥）
local function msg_line(msg, config)
  if type(msg) ~= "table" then return tostring(msg) end
  local role = msg.role or "?"
  local parts = { "[" .. role .. "]" }
  if msg.tool_call_id then parts[#parts + 1] = "(" .. msg.tool_call_id .. ")" end
  if msg.content and msg.content ~= "" then
    local c = redact(msg.content, config):gsub("\n", " "):gsub("\r", "")
    if #c > 1000 then c = c:sub(1, 997) .. "..." end
    parts[#parts + 1] = c
  end
  if msg.tool_calls then
    for _, tc in ipairs(msg.tool_calls) do
      local fn = tc and tc["function"]
      if fn then parts[#parts + 1] = "→tool:" .. tostring(fn.name or "?") end
    end
  end
  return table.concat(parts, " ")
end

-- 收集报告。config = 当前配置表；history = load_history() 结果（可选）。
-- 返回报告字符串。
local function collect(config, history)
  local lines = {}
  -- 统一获取 computer 模块（pcall 保护：某些环境无此模块/require 返回 nil）。
  -- 注意不能依赖全局 computer——pcall(computer.uptime) 的参数在 pcall 进入
  -- 前求值，全局缺失（真机 OpenOS）会直接崩溃而非被捕获。
  local ok_comp, computer = pcall(require, "computer")
  if not ok_comp or type(computer) ~= "table" then computer = nil end

  lines[#lines + 1] = "=== OC Agent Debug Report ==="
  -- 时间: os.date 在无 RTC 时返回 epoch (1970)，此时回退用 uptime
  do
    local ts
    local ok_d, d = pcall(os.date, "%Y-%m-%d %H:%M:%S")
    if ok_d and d and d:match("^20%d%d%-") then
      ts = d
    else
      local ok_u, u = false
      if computer then ok_u, u = pcall(computer.uptime) end
      ts = "uptime " .. ((ok_u and u and string.format("%.0f", u) .. "s") or "?")
    end
    lines[#lines + 1] = "Generated: " .. ts
  end
  lines[#lines + 1] = ""

  -- 版本
  local ver = "(未记录)"
  do
    local dir = type(AGENT_DIR) == "string" and AGENT_DIR or ""
    local vf = dir ~= "" and io.open(dir .. "/version.txt", "r")
    if vf then
      local v = vf:read("*a"):gsub("%s", "")
      vf:close()
      if v ~= "" then ver = v end
    end
  end
  lines[#lines + 1] = "Version: " .. ver

  -- 运行状态（computer 已在函数顶部统一获取，可能为 nil；
  -- pcall 参数求值陷阱同上：computer 为 nil 时须先判空再调用）
  local ok_uptime, uptime = false
  if computer then ok_uptime, uptime = pcall(computer.uptime) end
  local ok_mem, free_mem = false
  if computer then ok_mem, free_mem = pcall(computer.freeMemory) end
  local ok_addr, addr = false
  if computer then ok_addr, addr = pcall(computer.address) end
  lines[#lines + 1] = "Uptime: " .. (ok_uptime and string.format("%.1f", uptime) or "?") .. "s"
  lines[#lines + 1] = "Free memory: " .. (ok_mem and tostring(free_mem) or "?") .. " bytes"
  lines[#lines + 1] = "Computer address: " .. (ok_addr and tostring(addr) or "?")
  lines[#lines + 1] = ""

  -- 配置（脱敏：api_key/tavily_key 首尾4位，gist_token 完全遮蔽）
  lines[#lines + 1] = "--- Config ---"
  local cfg = config or {}
  lines[#lines + 1] = "model: " .. tostring(cfg.model or "?")
  lines[#lines + 1] = "api_url: " .. tostring(cfg.api_url or "?")
  lines[#lines + 1] = "api_key: " .. mask(cfg.api_key)
  lines[#lines + 1] = "tavily_key: " .. mask(cfg.tavily_key)
  lines[#lines + 1] = "gist_token: " .. mask_token(cfg.gist_token)
  lines[#lines + 1] = "subagent: " .. tostring(cfg.subagent or false)
  lines[#lines + 1] = ""

  -- 最近会话历史（默认最近 30 条，避免报告过大）
  local max_msgs = 30
  lines[#lines + 1] = "--- Recent history (last " .. max_msgs .. " of " .. tostring(history and #history or 0) .. ") ---"
  if history and #history > 0 then
    local start = math.max(1, #history - max_msgs + 1)
    for i = start, #history do
      lines[#lines + 1] = msg_line(history[i], config)
    end
  else
    lines[#lines + 1] = "(empty)"
  end

  -- 运行时诊断段（v0.3.56）: 内存曲线 / 最后一次内存裁剪 / 最后一次
  -- chat 请求。数据源 init.lua 的 DIAG 表（_G._AGENT_DIAG 全局挂载，
  -- 与 json 全局同先例）。用途: 对话卡死无反馈时（真机第 7 次现场，
  -- gist 5ff1d4——[mem] 裁剪后对话中断）报告可见:
  --   - mem curve: 内存下降路径（哪轮开始跌破阈值）
  --   - last mem trim: 裁剪事件（触发时间/前后 free/裁剪条数）——
  --     若 free_after 未回升说明 GC 未释放堆（裁剪无效）
  --   - last chat: 最后一次请求耗时与错误——elapsed 接近 retry_budget
  --     （默认 300s）说明端点慢/挂起；error 有值说明编码/请求失败
  -- v0.3.66 快照恢复（gist 535cfe 现场丢失教训）: 卡死时重启 agent
  -- 再 /debug，进程内 DIAG 已清空（历史是旧会话加载的，诊断全空）。
  -- 修复: init.lua 每次 chat/裁剪后写 <WRITABLE_BASE>/agent_diag.json，
  -- 此处进程内数据缺失时读文件恢复现场，并标注"（重启前快照）"。
  local diag = type(_G._AGENT_DIAG) == "table" and _G._AGENT_DIAG or nil
  local snapshot = false
  if not diag or (not diag.last_chat and not diag.last_trim) then
    local ok_cfg, cfg_mod = pcall(require, "agent.config")
    if ok_cfg and cfg_mod and cfg_mod.writable_base then
      local ok_f, f = pcall(io.open, cfg_mod.writable_base .. "/agent_diag.json", "r")
      if ok_f and f then
        local content = f:read("*a")
        f:close()
        local ok_j, snap = pcall(json.decode, content)
        -- v0.3.82 修复: 恢复条件补 chat_started/last_tool——卡死现场恰恰
        -- 只有这两个字段（chat 进行中未完成 / 工具执行中未完成），原
        -- 条件 (last_chat or last_trim) 把它们过滤掉 → 重启后显示
        -- "(never)"，诊断盲区重现（真机现场: gist dec2a65 后的
        -- 卡死报告历史 2 条但 last chat (never)、无 IN PROGRESS 标记）。
        if ok_j and type(snap) == "table"
            and (snap.last_chat or snap.last_trim
              or snap.chat_started or snap.last_tool) then
          diag = snap
          snapshot = true
        end
      end
    end
  end
  if diag then
    lines[#lines + 1] = ""
    lines[#lines + 1] = "--- Diagnostics ---"
    if snapshot then
      lines[#lines + 1] = "来源: agent_diag.json 重启前快照（本次进程无诊断数据）"
    end
    if diag.mem_curve and #diag.mem_curve > 0 then
      local pts = {}
      for _, p in ipairs(diag.mem_curve) do
        pts[#pts + 1] = string.format("%.1fs→%d", p.uptime or 0, p.free or 0)
      end
      lines[#lines + 1] = "mem curve (uptime→free): " .. table.concat(pts, ", ")
    else
      lines[#lines + 1] = "mem curve: (no samples)"
    end
    if diag.last_trim then
      local t = diag.last_trim
      lines[#lines + 1] = "last mem trim: uptime=" .. string.format("%.1fs", t.uptime or 0)
        .. " free_before=" .. tostring(t.free_before)
        .. " removed=" .. tostring(t.removed)
        .. " free_after=" .. tostring(t.free_after)
        .. (t.free_after and t.free_before and t.free_after < t.free_before
          and "  <-- GC 未释放堆（裁剪无效）" or "")
    else
      lines[#lines + 1] = "last mem trim: (never)"
    end
    if diag.last_chat then
      local c = diag.last_chat
      lines[#lines + 1] = "last chat: uptime=" .. string.format("%.1fs", c.uptime or 0)
        .. " elapsed=" .. string.format("%.1fs", c.elapsed or 0)
        .. " error=" .. tostring(c.error or "nil")
    else
      lines[#lines + 1] = "last chat: (never)"
    end
    -- 进行中标记（v0.3.80）: chat_started 有值 = 卡在 chat 请求进行中
    -- （未完成——last_chat 只有上一次成功的）；last_tool 有值 = 卡在
    -- 工具执行中（subagent_call 240s / shell 60s 等长阻塞工具）。
    -- 真机 gist dec2a65 现场（uptime 8.5h 卡死，快照只有上次成功的
    -- 6.8s chat）暴露盲区——卡住的那次请求/工具从未完成，无记录。
    if diag.chat_started then
      local c = diag.chat_started
      lines[#lines + 1] = ">> CHAT IN PROGRESS: started uptime=" .. string.format("%.1fs", c.uptime or 0)
        .. " est_bytes=" .. tostring(c.est or 0)
        .. "  <-- 卡在 chat 请求进行中（从未完成）"
    end
    if diag.last_tool then
      local t = diag.last_tool
      lines[#lines + 1] = ">> TOOL IN PROGRESS: " .. tostring(t.name or "?")
        .. " started uptime=" .. string.format("%.1fs", t.uptime or 0)
        .. "  <-- 卡在工具执行中（从未完成）"
    end
  end

  return table.concat(lines, "\n")
end

-- 上传到 GitHub Gist。返回 (url, err)。
-- v0.3.73 超时保护（真机多次卡死根因，gist 852193/用户反复反馈）:
-- OC internet.request 连接阶段**无超时**（http.lua 的 120s/300s 保护只
-- 覆盖响应迭代与重试预算——连接挂起时 once 不返回，预算检查不到）。
-- 用户网络 api.github.com 不可达时 TCP connect 永久挂起 → /debug 卡在
-- "Uploading..."。修复: 上传跑在 thread 里，外部 waitForAll 带超时
-- （默认 30s，config.debug_upload_timeout 可调）；超时放弃线程返回
-- 提示（报告已写本地）。thread 库不可用（测试/精简环境）时回退同步
-- 调用（行为同旧版）。
local function upload(report, token)
  if not token or token == "" then
    return nil, "no gist token configured (use /gist-token <token>)"
  end
  local http = require("agent.http")
  local body = json.encode({
    description = "OC Agent debug report",
    public = false,
    files = { ["debug_report.txt"] = { content = report } },
  })
  local headers = {
    ["Content-Type"] = "application/json",
    ["Authorization"] = "token " .. token,
    ["Accept"] = "application/vnd.github+json",
    ["User-Agent"] = "oc-agent",
  }
  local thread_ok, thread = pcall(require, "thread")
  if not thread_ok or not thread or not thread.create or not thread.waitForAll then
    -- 无 thread（测试/精简环境）: 同步调用（行为同旧版）
    local code, resp, err = http.post("https://api.github.com/gists", headers, body)
    if err then return nil, "network: " .. tostring(err) end
    if code ~= 201 then
      return nil, "HTTP " .. tostring(code) .. ": " .. tostring(resp):sub(1, 200)
    end
    local url = resp and resp:match('"html_url"%s*:%s*"([^"]+)"')
    if not url then url = resp and resp:match('"url"%s*:%s*"([^"]+)"') end
    return url or "(gist created, no url parsed)"
  end

  -- 线程化 + 超时: 连接挂起不再阻塞主循环
  local result = {}
  local t = thread.create(function()
    local code, resp, err = http.post("https://api.github.com/gists", headers, body)
    result.code, result.resp, result.err = code, resp, err
  end)
  local timeout = 30
  local ok_cfg, cfg = pcall(require, "agent.config")
  if ok_cfg and cfg and cfg.load then
    local ok_c, c = pcall(cfg.load)
    if ok_c and c and c.debug_upload_timeout then
      timeout = tonumber(c.debug_upload_timeout) or 30
    end
  end
  local ok_w, werr = pcall(thread.waitForAll, {t}, timeout)
  if not ok_w or not werr then
    -- 超时或 waitForAll 失败: 放弃（线程后台继续，连接最终由
    -- http.lua 响应超时兜底；不再阻塞用户）
    return nil, "upload timeout after " .. timeout .. "s (network unreachable?) — report saved locally"
  end
  if result.err then return nil, "network: " .. tostring(result.err) end
  if result.code ~= 201 then
    return nil, "HTTP " .. tostring(result.code) .. ": " .. tostring(result.resp):sub(1, 200)
  end
  local url = result.resp and result.resp:match('"html_url"%s*:%s*"([^"]+)"')
  if not url then url = result.resp and result.resp:match('"url"%s*:%s*"([^"]+)"') end
  return url or "(gist created, no url parsed)"
end

return {
  collect = collect,
  upload = upload,
  mask = mask,
  redact = redact,
}
end

-- agent.agent.tui (embedded module)
package.preload["agent.tui"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.tui — OpenComputers 终端 UI（参考 DonChong2000/oc-ai 的
-- lib/oc-code/tui.lua 架构）。
--
-- 四区布局: header(第1行) / 内容区(2..h-3) / 状态栏(h-1) / 输入行(h)。
-- 单色模式: gpu.getDepth()==1 → monoColors（机器人 T1 GPU 1-bit 屏）。
-- 所有 gpu 调用 pcall 包裹: 渲染异常不拖垮 agent（调用方回退 REPL）。
-- 兼容接口（与 oc-ai runLoop 同构）: init/print/printRole/printToolCall/
-- printToolResult/setStatus/readInput/scrollUp/scrollDown/scrollToBottom/
-- isRunning/stop/clear/cleanup。扩展: setStatusData(fn)（状态栏右侧动态
-- 数据: 上下文占用/cache）、setCompletions(list)（Tab 补全候选）。
-- ═══════════════════════════════════════════════════════════════

local ok_c, component = pcall(require, "component")
local ok_t, term = pcall(require, "term")
local ok_e, event = pcall(require, "event")
local ok_k, keyboard = pcall(require, "keyboard")
-- computer 模块（pcall 保护）：readInput 光标闪烁计时用。**不能依赖全局
-- computer**——荒野大师/OCEmu 无全局（debug.lua:59 同款坑：oc_mock 注入
-- 全局 computer 掩盖，真机崩溃）。
local ok_cp, computer = pcall(require, "computer")
-- 缺库降级: 无 GPU/键盘组件时绘制静默失败，纯逻辑（history/滚动/补全）
-- 仍可用（测试环境/机器人）。
if not ok_c then component = {} end
if not ok_t then term = {} end
if not ok_e then event = {} end
if not ok_k then keyboard = {} end
if not ok_cp or type(computer) ~= "table" then computer = nil end

-- 计时源：优先 computer.uptime()（真实 OC 开机秒），缺失时 os.clock()
-- 兜底（闪烁计时仅装饰，精度无关紧要）
local function now_seconds()
  if computer and computer.uptime then
    local ok_u, u = pcall(computer.uptime)
    if ok_u and type(u) == "number" then return u end
  end
  return os.clock()
end

-- UTF-8 显示宽度（OC 等宽屏: ASCII 1 列, CJK/多字节 2 列——中文按 1 字符
-- 计算会导致换行/光标/截断全部错位，长中文行溢出炸布局）
local function ulen(s)
  local n = 0
  for ch in tostring(s):gmatch("([\1-\127\194-\244][\128-\191]*)") do
    if ch:byte(1) < 128 then n = n + 1 else n = n + 2 end
  end
  return n
end
local function usub(s, i, j)
  local str = tostring(s)
  local start_char, end_char = math.max(1, i or 1), j or -1
  local out, count = {}, 0
  for ch in str:gmatch("([\1-\127\194-\244][\128-\191]*)") do
    count = count + 1
    if count >= start_char and (end_char < 0 or count <= end_char) then
      out[#out + 1] = ch
    end
    if end_char >= 0 and count > end_char then break end
  end
  return table.concat(out)
end

local tui = {}

-- 彩色方案（暗底 + 角色色，opencode TUI 风格）
tui.colors = {
  background = 0x000000, foreground = 0xffffff,
  status = 0x1b1b2f, statusText = 0x9aa0b0,
  prompt = 0x4ec9b0, user = 0x8ab4f8, assistant = 0xffffff,
  tool = 0xf0a35e, toolName = 0xffd966, error = 0xff6b6b, dim = 0x888888,
}
-- 单色方案（1-bit: 状态栏/输入行反白区分，其余正常）
tui.monoColors = {
  background = 0x000000, foreground = 0xffffff,
  status = 0xffffff, statusText = 0x000000,
  prompt = 0xffffff, user = 0xffffff, assistant = 0xffffff,
  tool = 0xffffff, toolName = 0xffffff, error = 0xffffff, dim = 0xffffff,
}

local state = {}
local completionHandlers = {}  -- {prefix = {candidates = {cmd, desc}...}}

-- 解析: 按字节找分隔符（OC gpu 文本按字符定位，ansi 处理走 unicode）
local function char_count_before(s, sub)
  local idx = s:find(sub, 1, true)
  if not idx then return ulen(s) end
  return ulen(s:sub(1, idx - 1))
end

-- 初始化（config.monochrome 强制单色）
function tui.init(config)
  config = config or {}
  if config.monochrome then tui.colors = tui.monoColors end
  local ok, w, h = pcall(function()
    -- 注意: 不能写 `return component.gpu and component.gpu.getResolution()`
    -- —— Lua 的 and 只保留第一个返回值, getResolution 的高度会丢失(h=nil),
    -- 导致恒走兜底 80x25。须显式分支保留多返回值。
    local g = component.gpu
    if g then return g.getResolution() end
    return nil
  end)
  -- 异常分辨率兜底（某些模拟器/远控返回怪异值 → 标准 80x25）
  if not ok or type(w) ~= "number" or type(h) ~= "number"
      or w < 20 or h < 8 or w > 320 or h > 160 then
    w, h = 80, 25
  end
  state.width, state.height = w, h
  state.running = true
  state.scrollOffset = 0
  -- 滚动型渲染探测（荒野大师等终端滚动型模拟器）：写入最底行 y=h 会触发
  -- 整屏上滚（帧缓冲模拟器如 ocvm/OCEmu 无此行为）。探测：先在 y=1 写
  -- 标记再写 y=h，标记被顶走即滚动型。**旧版先读后写是 bug——启动时
  -- 屏幕为空（term.clear 后），滚动后 y=1 被原 y=2 空行顶上 c1==c2 恒等，
  -- 探测永远失败（真机实证：v0.3.39 scrollSafe 未生效，状态栏内容滚进
  -- 内容区）。**set 单点与 fill 整行两种写入都测（滚动触发条件未知）。
  -- scrollSafe = true 时布局整体上移一行（最底行 h 永不写入），杜绝滚动。
  state.scrollSafe = false
  local ok_g, gpu0 = pcall(function() return component.gpu end)
  if ok_g and gpu0 and gpu0.set and gpu0.get and gpu0.fill then
    local function scroll_probe(write_bottom)
      pcall(gpu0.fill, 1, 1, 3, 3, " ")     -- 清左上角（含 y=1 标记位）
      pcall(gpu0.set, 1, 1, "M")            -- 写标记
      local ok1, c1 = pcall(gpu0.get, 1, 1)
      if not (ok1 and c1 == "M") then return false end
      pcall(write_bottom)
      local ok2, c2 = pcall(gpu0.get, 1, 1)
      return ok2 and c1 ~= c2
    end
    -- 测 1: 单点 set 写 y=h
    if scroll_probe(function() pcall(gpu0.set, 1, h, "Z") end) then
      state.scrollSafe = true
    else
      -- 测 2: fill 整行写 y=h（部分模拟器仅整行写入触发滚动）
      if scroll_probe(function() pcall(gpu0.fill, 1, h, 5, 1, "X") end) then
        state.scrollSafe = true
      end
    end
    pcall(gpu0.fill, 1, 1, 1, h, " ")  -- 清理探测痕迹（init 末尾 term.clear 再清一次）
  end
  state.history = {}
  state.inputBuffer = ""
  state.inputCursor = 0
  state.cmdHistory = {}
  state.cmdHistoryIndex = 0
  state.savedInput = ""
  state.status = "Ready"
  state.statusData = nil
  state.completions = {}
  state.completionCycle = nil
  pcall(function()
    term.clear()
    tui.drawHeader()
    tui.drawStatus()
    tui.drawInput()
  end)
end

-- 状态栏右侧动态数据提供者（init.lua 注入: 上下文占用/cache 等）
function tui.setStatusData(fn)
  state.statusData = fn
end

-- Tab 补全候选（命令/工具名列表）
function tui.setCompletions(list)
  state.completions = list or {}
end

-- 绘制 header（第 1 行）
function tui.drawHeader()
  local g = component.gpu
  if not g then return end  -- 无 gpu（测试/降级环境）静默
  g.setBackground(tui.colors.status)
  g.setForeground(tui.colors.statusText)
  g.fill(1, 1, state.width, 1, " ")
  g.setForeground(tui.colors.toolName)
  g.set(2, 1, "OC Agent")
  g.setForeground(tui.colors.statusText)
  -- hint 只宣传实际可用的滚动方式：PgUp/PgDn 在部分游戏/远程环境
  -- 不产生键码（荒野大师实测不可用），/up /down 命令是通用兜底
  local hint = "/help | /up /down scroll | /exit"
  if state.width >= ulen(hint) + 16 then
    g.set(state.width - ulen(hint) - 1, 1, hint)
  end
end

-- 绘制状态栏（h-1 行: status 左 + 动态数据右 + scroll 指示; scrollSafe 时上移一行）
function tui.drawStatus()
  local g = component.gpu
  if not g then return end  -- 无 gpu（测试/降级环境）静默
  local y = state.height - 1 - (state.scrollSafe and 1 or 0)
  g.setBackground(tui.colors.status)
  g.setForeground(tui.colors.statusText)
  g.fill(1, y, state.width, 1, " ")
  g.set(2, y, state.status)
  -- 多行输入指示（粘贴多行时: 显示行数，提示 Enter 提交全部）
  if state.inputBuffer and state.inputBuffer:find("\n", 1, true) then
    local n = 0
    for _ in state.inputBuffer:gmatch("\n") do n = n + 1 end
    g.setForeground(tui.colors.tool)
    g.set(ulen(state.status) + 4, y, "ML:" .. tostring(n + 1) .. " (Enter=send)")
    g.setForeground(tui.colors.statusText)
  end
  if state.statusData then
    -- pcall 防御: 回调内任何异常（如 provider usage 结构怪异）都不应
    -- 中断状态栏绘制——否则状态栏只剩 status 文本（真机曾现"完成后
    -- 只剩 Ready，model/ctx/cache 全丢"）
    local ok_data, data = pcall(state.statusData)
    if ok_data and data and data ~= "" then
      local maxw = state.width - 8
      if ulen(data) > maxw then data = usub(data, 1, maxw - 1) .. "~" end
      g.set(state.width - ulen(data) - 1, y, data)
    end
  end
  if state.scrollOffset > 0 then
    local st = "[Scroll " .. tostring(state.scrollOffset) .. "]"
    g.setForeground(tui.colors.tool)
    g.set(state.width - ulen(st) - 1, y, st)
    g.setForeground(tui.colors.statusText)
  end
  g.setBackground(tui.colors.background)
  g.setForeground(tui.colors.foreground)
end

function tui.setStatus(msg)
  state.status = msg or "Ready"
  pcall(tui.drawStatus)
end

-- 内容区边界（含滚动窗口高度）; scrollSafe 时整体上移一行（内容区少 1 行）
local function getContentBounds()
  return 2, 2, state.width - 2, state.height - 3 - (state.scrollSafe and 1 or 0)
end

-- 逐词换行 + 长词硬断（中文按 unicode 字符）
local function wrapText(str, width)
  local lines = {}
  for line in tostring(str):gmatch("([^\n]*)\n?") do
    if ulen(line) <= width then
      lines[#lines + 1] = line
    else
      local current = ""
      for word in line:gmatch("%S+") do
        if ulen(current) + ulen(word) + 1 <= width then
          current = current == "" and word or (current .. " " .. word)
        else
          if current ~= "" then lines[#lines + 1] = current end
          if ulen(word) > width then
            while ulen(word) > width do
              lines[#lines + 1] = usub(word, 1, width)
              word = usub(word, width + 1)
            end
            current = word
          else
            current = word
          end
        end
      end
      if current ~= "" then lines[#lines + 1] = current end
    end
  end
  return lines
end

-- 输出到内容区（自动滚动到底）
function tui.print(msg, color)
  local _, _, w = getContentBounds()
  color = color or tui.colors.foreground
  for _, line in ipairs(wrapText(msg, w)) do
    state.history[#state.history + 1] = {text = line, color = color}
  end
  state.scrollOffset = 0
  pcall(tui.redrawContent)
end

-- 角色前缀输出
function tui.printRole(role, msg)
  local color, prefix
  if role == "user" then color, prefix = tui.colors.user, "> "
  elseif role == "assistant" then color, prefix = tui.colors.assistant, ""
  elseif role == "tool" then color, prefix = tui.colors.tool, "  "
  elseif role == "error" then color, prefix = tui.colors.error, "Error: "
  else color, prefix = tui.colors.foreground, "" end
  tui.print(prefix .. msg, color)
end

function tui.printToolCall(name, args)
  tui.print(">> " .. tostring(name), tui.colors.toolName)
  if args then
    local s = type(args) == "string" and args or json_encode(args)
    if ulen(s) > 100 then s = usub(s, 1, 97) .. "..." end
    tui.print("   " .. s, tui.colors.dim)
  end
end

function tui.printToolResult(name, result)
  local s = type(result) == "string" and result or json_encode(result)
  if ulen(s) > 200 then s = usub(s, 1, 197) .. "..." end
  tui.print("<< " .. s, tui.colors.dim)
end

local function json_encode(v)
  local ok, out = pcall(function() return require("agent.json").encode(v) end)
  return ok and out or tostring(v)
end

-- 重绘内容区（可见窗口 = 底部 h 行 - scrollOffset）
function tui.redrawContent()
  local g = component.gpu
  local x, y, w, h = getContentBounds()
  g.setBackground(tui.colors.background)
  g.fill(x - 1, y, w + 2, h, " ")
  local startIdx = math.max(1, #state.history - h + 1 - state.scrollOffset)
  local endIdx = math.min(#state.history, startIdx + h - 1)
  local row = y
  for i = startIdx, endIdx do
    local entry = state.history[i]
    g.setForeground(entry.color or tui.colors.foreground)
    g.set(x, row, usub(entry.text, 1, w))
    row = row + 1
  end
  g.setForeground(tui.colors.foreground)
  tui.drawStatus()
  tui.drawInput()
end

function tui.scrollUp(lines)
  lines = lines or 1
  local _, _, _, h = getContentBounds()
  local maxScroll = math.max(0, #state.history - h)
  state.scrollOffset = math.min(maxScroll, state.scrollOffset + lines)
  pcall(tui.redrawContent)
end

function tui.scrollDown(lines)
  lines = lines or 1
  state.scrollOffset = math.max(0, state.scrollOffset - lines)
  pcall(tui.redrawContent)
end

function tui.scrollToBottom()
  state.scrollOffset = 0
  pcall(tui.redrawContent)
end

function tui.scrollToTop()
  local _, _, _, h = getContentBounds()
  state.scrollOffset = math.max(0, #state.history - h)
  pcall(tui.redrawContent)
end

-- 翻页步长（半屏）——/up /down 命令与 PgUp/PgDn 失效时的兜底
-- scrollSafe 时内容区矮 1 行 → 步长同步 -1，与内容区一致
function tui.pageStep()
  return math.max(1, state.height - 4 - (state.scrollSafe and 1 or 0))
end

-- 多行 buffer 支持: 粘贴内容（含 \n）完整保留，输入行只显示最后一行，
-- 编辑限定在最后一行（跨行编辑不做），Enter 提交整个多行内容。
-- 返回 buffer 中最后一个 \n 的【字符】位置（无则 0）——与 inputCursor
-- 的字符语义一致（usub 操作字符，避免中文混用时字节/字符错位）。
local function lastLineStart(buffer)
  local idx = 0
  local pos = 0
  for ch in tostring(buffer):gmatch("([\1-\127\194-\244][\128-\191]*)") do
    pos = pos + 1
    if ch == "\n" then idx = pos end
  end
  return idx
end

-- 绘制输入行（底部: 提示符 + 最后一行文本 + 反色块光标 + Tab 候选提示;
-- scrollSafe 时上移一行, 最底行 h 永不写入——杜绝终端滚动型模拟器触发整屏上滚）
-- v0.3.72 拖选高亮: state.sel = {a=字符索引, b=字符索引}（输入缓冲内），
-- a==b 时无选中。选中段用反色背景绘制（先画文本→再画选中段覆盖）。
-- GTNH 组件无 setClipboard API——复制目标为 state.clipboard（进程内
-- 剪贴板，Ctrl+V 粘贴优先使用），跨游戏剪贴板不可行。
function tui.drawInput()
  local g = component.gpu
  if not g then return end  -- 无 gpu（测试/降级环境）静默
  local y = state.height - (state.scrollSafe and 1 or 0)
  g.setBackground(tui.colors.background)
  g.fill(1, y, state.width, 1, " ")
  local line_start = lastLineStart(state.inputBuffer)
  local multiline = line_start > 0
  g.setForeground(tui.colors.prompt)
  g.set(2, y, multiline and ">> " or "> ")
  g.setForeground(tui.colors.foreground)
  local inputStart = multiline and 5 or 4
  local maxWidth = state.width - inputStart - 1
  -- 只显示最后一行（历史行提交时在内容区打印）
  local displayText = multiline and usub(state.inputBuffer, line_start + 1)
    or state.inputBuffer
  local cursorInLine = math.max(0, state.inputCursor - line_start)
  -- 光标 x 位置按显示宽度（中文占 2 列，字符索引会错位）
  local cursorX = inputStart + ulen(usub(displayText, 1, cursorInLine))
  if ulen(displayText) > maxWidth then
    local start = math.max(1, cursorInLine - maxWidth + 10)
    displayText = usub(displayText, start, start + maxWidth - 1)
  end
  g.set(inputStart, y, displayText)
  -- 选中段高亮（先画文本后覆盖：反色背景 + 反色前景；光标在下）
  local sel = state.sel
  if sel and sel.a ~= sel.b then
    local sa, sb = math.min(sel.a, sel.b), math.max(sel.a, sel.b)
    -- 相对最后一行（仅选中当前显示行内的部分）
    local lo, hi = math.max(sa - line_start, 1), math.min(sb - line_start, ulen(displayText))
    if lo <= hi then
      local x0 = inputStart + ulen(usub(displayText, 1, lo - 1))
      local x1 = inputStart + ulen(usub(displayText, 1, hi))
      if x1 > state.width - 1 then x1 = state.width - 1 end
      local w = x1 - x0
      if w > 0 then
        g.setBackground(tui.colors.foreground)
        g.setForeground(tui.colors.background)
        g.set(x0, y, usub(displayText, lo, hi))
        -- 填充剩余宽度（选中到行尾）
        if x0 + w < state.width - 1 then
          g.fill(x0 + w, y, state.width - 1 - x0 - w, 1, " ")
        end
        g.setBackground(tui.colors.background)
        g.setForeground(tui.colors.foreground)
      end
    end
  end
  -- 反色块光标
  if cursorX <= state.width - 1 then
    local ch = usub(displayText, cursorInLine + 1, cursorInLine + 1)
    if ch == "" then ch = " " end
    g.setBackground(tui.colors.foreground)
    g.setForeground(tui.colors.background)
    g.set(cursorX, y, ch)
    g.setBackground(tui.colors.background)
    g.setForeground(tui.colors.foreground)
  end
  -- Tab 补全候选提示（输入行末尾）
  if state.completionCycle and state.completionCycle[2] then
    local hint = "Tab: " .. tostring(state.completionCycle[2].cmd)
    if ulen(displayText) + ulen(hint) + inputStart < state.width then
      g.setForeground(tui.colors.tool)
      g.set(state.width - ulen(hint) - 1, y, hint)
      g.setForeground(tui.colors.foreground)
    end
  end
  pcall(term.setCursor, cursorX, y)
  pcall(term.setCursorBlink, false)
end

-- 补全候选: 命令 + 工具名 + 注册前缀处理器
local function completionCandidates(buffer)
  local results = {}
  local lower = buffer:lower()
  -- 前缀处理器（completionHandlers，如 /model 的模型候选）
  for prefix, h in pairs(completionHandlers) do
    if buffer:sub(1, #prefix) == prefix then
      local extra = h.handler(buffer)
      if extra then
        for _, cand in ipairs(extra) do results[#results + 1] = cand end
      end
    end
  end
  -- 静态候选（命令 + 工具名）
  for _, cand in ipairs(state.completions) do
    local c = type(cand) == "string" and cand or cand.cmd
    if lower == "" or c:lower():find(lower, 1, true) == 1 then
      results[#results + 1] = type(cand) == "string" and {cmd = cand, desc = ""} or cand
    end
  end
  -- 去重保序
  local seen, dedup = {}, {}
  for _, r in ipairs(results) do
    if not seen[r.cmd] then seen[r.cmd] = true dedup[#dedup + 1] = r end
  end
  return dedup
end

function tui.registerCompletion(prefix, handler, label)
  completionHandlers[prefix] = {handler = handler, label = label}
end

-- 事件驱动输入: 键盘编辑 + 历史浏览 + Tab 补全 + 滚动 + Ctrl+C。
-- 无 keyboard 组件时回退 io.read（机器人）。
function tui.readInput(on_event)
  -- on_event（v0.3.84）: 可选回调，事件循环收到非键盘事件（如
  -- modem_message——explorer 子代理的文件服务请求）时转发，避免事件被
  -- readInput 消费丢弃。回调签名 on_event(ev, args_table)。返回 true
  -- 表示事件已消费（不打断输入循环）。
  -- 键盘可用性检测（荒野大师/OCEmu 同款 OpenOS 库缺 keyboard.isAvailable，
  -- 但组件存在且事件驱动正常——真机探针实证 key_down 全键标准格式到达）：
  -- isAvailable 缺失时回退到组件检测；组件可用即走事件驱动分支，否则
  -- io.read 回退（机器人）。此前缺失误判导致每次 readInput 走 io.read
  -- 回退（io.write 直写终端层 + 阻塞读行）——Tab/方向键/Ctrl 组合全部
  -- "无反应"、空回车多状态栏，均由此产生。
  local ok_kb, kb_avail = pcall(function()
    if keyboard.isAvailable then return keyboard.isAvailable() end
    local ok_c, comp = pcall(require, "component")
    return ok_c and comp.isAvailable and comp.isAvailable("keyboard")
  end)
  if not ok_kb or not kb_avail then
    io.write("> ")
    io.flush()
    local ok, line = pcall(io.read, "*l")
    if not ok then return nil end
    line = (line or ""):gsub("\r?\n", "")
    -- 与事件驱动分支一致：提交内容进内容区（主循环不回显，统一由
    -- readInput 打印——v0.3.40 键盘检测修复后事件驱动激活，双重回显
    -- 曾导致同一消息两行）
    if line ~= "" then tui.print("> " .. line, tui.colors.user) end
    return line
  end

  state.inputBuffer = ""
  state.inputCursor = 0
  state.completionCycle = nil
  local cursorVisible = true
  local lastBlink = now_seconds()

  pcall(tui.drawInput)

  while true do
    local sig = {event.pull(0.25)}
    local ev, _, char, code = sig[1], sig[2], sig[3], sig[4]

    -- 非键盘事件转发（v0.3.84）: modem_message 等交给 on_event 回调
    -- （主代理文件服务用——explorer 子代理读主代理硬盘）。不打断
    -- 输入循环，事件不丢失。回调签名 on_event(sig_table)（sig[1]=ev,
    -- sig[3]=sender, sig[4]=port, sig[6]=payload...），返回 true 表示
    -- 已消费。
    if on_event and ev ~= "key_down" and ev ~= "interrupted"
        and ev ~= "key_up" and ev ~= "clipboard" then
      local handled = on_event(sig)
      if handled then
        pcall(tui.drawInput)
        -- fallthrough: 继续输入循环（事件已消费）
      end
    end

    -- 光标闪烁
    local now = now_seconds()
    if now - lastBlink >= 0.5 then
      cursorVisible = not cursorVisible
      lastBlink = now
      -- 简化: 闪烁只做定时重绘提示（块光标常亮，不闪烁——机器人帧率友好）
    end

    if ev == "interrupted" then
      -- Ctrl+C 双语义（v0.3.72）: 游戏端 Ctrl+C 发 interrupted 事件。
      -- 输入行有选中文本 → 复制到进程内剪贴板 + 清除选中 + 继续输入
      -- （不中断——用户意图是复制，不是中断）；
      -- 无选中 → 原有中断行为（return nil 退出输入循环）。
      if state.sel and state.sel.a ~= state.sel.b then
        local sa, sb = math.min(state.sel.a, state.sel.b),
          math.max(state.sel.a, state.sel.b)
        state.clipboard = usub(state.inputBuffer, sa + 1, sb)
        tui.setStatus("Copied " .. ulen(state.clipboard) .. " chars (Ctrl+V to paste)")
        state.sel = nil
        state.sel_active = nil
        pcall(tui.drawInput)
      else
        return nil
      end
    elseif ev == "key_down" then
      local ch = char or 0
      local line_start = lastLineStart(state.inputBuffer)  -- 编辑边界（最后一行起点）
      if ch == 13 then -- Enter
        local line = state.inputBuffer
        if line == "" or line:match("^%s+$") then
          -- 空回车/空白回车: 留在输入循环（重绘输入行）——不返回主循环，
          -- 避免终端换行/状态栏闪烁等副作用。
          -- 空白字符（空格/全角空格/Tab）必须同样拦截：否则空白消息被
          -- 当真输入提交 → Thinking 状态 + 完整请求 → 空回答重试网再一轮
          -- → 状态栏 Ready→Thinking→...反复切换（真机"多个状态栏"根因）
          state.completionCycle = nil
          pcall(tui.drawInput)
        else
          state.cmdHistory[#state.cmdHistory + 1] = line
          if #state.cmdHistory > 50 then table.remove(state.cmdHistory, 1) end
          tui.print("> " .. line, tui.colors.user)
          state.cmdHistoryIndex = 0
          state.savedInput = ""
          state.completionCycle = nil
          return line
        end
      elseif ch == 8 or code == 14 then -- Backspace（限最后一行，不删 \n）
        if state.inputCursor > line_start then
          state.inputBuffer = usub(state.inputBuffer, 1, state.inputCursor - 1)
            .. usub(state.inputBuffer, state.inputCursor + 1)
          state.inputCursor = state.inputCursor - 1
          state.completionCycle = nil
        end
      elseif code == 203 then -- Left（不跨行）
        if keyboard.isControlDown and keyboard.isControlDown() then
          -- Ctrl+Left: 前一个单词边界（字符索引）
          local pos = state.inputCursor
          while pos > line_start and usub(state.inputBuffer, pos, pos):match("%s") do
            pos = pos - 1
          end
          while pos > line_start and not usub(state.inputBuffer, pos, pos):match("%s") do
            pos = pos - 1
          end
          state.inputCursor = pos
        elseif state.inputCursor > line_start then
          state.inputCursor = state.inputCursor - 1
        end
        state.completionCycle = nil
      elseif code == 205 then -- Right
        if keyboard.isControlDown and keyboard.isControlDown() then
          -- Ctrl+Right: 下一个单词边界（字符索引）
          local len = ulen(state.inputBuffer)
          local pos = state.inputCursor
          while pos < len and not usub(state.inputBuffer, pos + 1, pos + 1):match("%s") do
            pos = pos + 1
          end
          while pos < len and usub(state.inputBuffer, pos + 1, pos + 1):match("%s") do
            pos = pos + 1
          end
          state.inputCursor = pos
        elseif state.inputCursor < ulen(state.inputBuffer) then
          state.inputCursor = state.inputCursor + 1
        end
        state.completionCycle = nil
      elseif code == 199 then -- Home（行首; Ctrl=滚到顶）
        if keyboard.isControlDown and keyboard.isControlDown() then
          tui.scrollToTop()
        else
          state.inputCursor = line_start
        end
      elseif code == 207 then -- End（buffer 尾 = 最后一行尾; Ctrl=滚到底）
        if keyboard.isControlDown and keyboard.isControlDown() then
          tui.scrollToBottom()
        else
          state.inputCursor = ulen(state.inputBuffer)
        end
      elseif code == 211 then -- Delete（最后一行内）
        local len = ulen(state.inputBuffer)
        if state.inputCursor < len then
          state.inputBuffer = usub(state.inputBuffer, 1, state.inputCursor)
            .. usub(state.inputBuffer, state.inputCursor + 2)
        end
        state.completionCycle = nil
      elseif code == 200 then -- Up: Ctrl=上滚 1 行; 否则历史上翻（多行 buffer 时禁用）
        if keyboard.isControlDown and keyboard.isControlDown() then
          tui.scrollUp(1)
        elseif line_start == 0 and #state.cmdHistory > 0 then
          if state.cmdHistoryIndex == 0 then state.savedInput = state.inputBuffer end
          if state.cmdHistoryIndex < #state.cmdHistory then
            state.cmdHistoryIndex = state.cmdHistoryIndex + 1
            state.inputBuffer = state.cmdHistory[#state.cmdHistory - state.cmdHistoryIndex + 1]
            state.inputCursor = ulen(state.inputBuffer)
          end
        end
      elseif code == 208 then -- Down: Ctrl=下滚 1 行; 否则历史下翻（多行时禁用）
        if keyboard.isControlDown and keyboard.isControlDown() then
          tui.scrollDown(1)
        elseif line_start == 0 and state.cmdHistoryIndex > 0 then
          state.cmdHistoryIndex = state.cmdHistoryIndex - 1
          if state.cmdHistoryIndex == 0 then
            state.inputBuffer = state.savedInput
          else
            state.inputBuffer = state.cmdHistory[#state.cmdHistory - state.cmdHistoryIndex + 1]
          end
          state.inputCursor = ulen(state.inputBuffer)
        end
      elseif code == 201 then -- PgUp: 上滚
        tui.scrollUp(tui.pageStep())
      elseif code == 209 then -- PgDn: 下滚
        tui.scrollDown(tui.pageStep())
      elseif ch == 27 then -- Esc: 关闭补全循环（oc-ai 同）
        state.completionCycle = nil
      elseif ch == 9 or code == 15
          or (ch == 32 and keyboard.isControlDown and keyboard.isControlDown()) then
        -- 补全触发: Tab（char 或 code 双判断——oc-ai 用 char==9）或 Ctrl+Space。
        -- 荒野大师全屏 TUI 实测: Home/End/方向键/Ctrl 组合全有效但 Tab 事件
        -- 被游戏客户端拦截（Minecraft Tab=玩家列表），故加 Ctrl+Space 备用触发。
        local cands = completionCandidates(state.inputBuffer)
        -- 可见诊断反馈: 无候选/有候选都更新状态栏, 用于区分
        -- "Tab 事件没到达"(状态栏无变化) vs "候选为空"(显示 Tab: no match)
        if #cands > 0 then
          if not state.completionCycle then state.completionCycle = {cands, cands[1]} end
          state.inputBuffer = state.completionCycle[2].cmd
          state.inputCursor = ulen(state.inputBuffer)
          tui.setStatus("Tab: " .. state.completionCycle[2].cmd
            .. (#cands > 1 and (" (" .. #cands .. " candidates)") or ""))
        else
          tui.setStatus("Tab: no match")
        end
      elseif ch >= 32 and ch < 127 then -- 可打印 ASCII
        -- Ctrl+C 复制选中（v0.3.72）: Ctrl+C 时 ch==3（ETX）。
        -- 有选中 → 复制到进程内剪贴板 + 清除选中；无选中 → 落到
        -- 下方原 Ctrl+C 中断处理（读事件循环 break）。
        if ch == 3 and state.sel and state.sel.a ~= state.sel.b then
          local sa, sb = math.min(state.sel.a, state.sel.b),
            math.max(state.sel.a, state.sel.b)
          state.clipboard = usub(state.inputBuffer, sa + 1, sb)
          tui.setStatus("Copied " .. ulen(state.clipboard) .. " chars (Ctrl+V to paste)")
          state.sel = nil
          state.sel_active = nil
          pcall(tui.drawInput)
        else
          -- 有输入时清除选中（高亮区间基于旧文本，输入后错位）
          state.sel = nil
          state.sel_active = nil
          state.inputBuffer = usub(state.inputBuffer, 1, state.inputCursor)
            .. string.char(ch)
            .. usub(state.inputBuffer, state.inputCursor + 1)
          state.inputCursor = state.inputCursor + 1
          state.completionCycle = nil
        end
      else
        -- 诊断（v0.3.29 临时）: 未匹配任何分支的 key_down——用于定位荒野大师
        -- 真机 Tab 无反应：若 Tab 事件到达但 char/code 值不同，会落入此分支
        -- 并显示实际值；若状态栏仍无变化则事件根本未到达 agent。
        tui.setStatus("kd?" .. tostring(char) .. "/" .. tostring(code))
      end
      pcall(tui.drawInput)
    elseif ev == "clipboard" then
      if char then
        -- v0.3.72: 优先粘贴进程内剪贴板（Ctrl+C 复制的选中文本）——
        -- 有内部剪贴板时用它（避免游戏剪贴板覆盖刚复制的文本）；
        -- 否则用游戏剪贴板内容（原有 Ctrl+V 行为）。
        local paste = state.clipboard and #state.clipboard > 0
          and state.clipboard or char
        state.inputBuffer = usub(state.inputBuffer, 1, state.inputCursor)
          .. paste
          .. usub(state.inputBuffer, state.inputCursor + 1)
        state.inputCursor = state.inputCursor + ulen(paste)
        state.completionCycle = nil
        state.sel = nil
        state.sel_active = nil
        pcall(tui.drawInput)
      end
    elseif ev == "touch" or ev == "drag" then
      -- 指针定位 + 拖选（v0.3.68 点击定位；v0.3.72 拖选高亮+Ctrl+C
      -- 复制）: screen 组件发 touch/drag (x, y, button, player)。
      -- 输入行内:
      --   touch 按下 → 起点 + 定位光标（清除旧选中）
      --   drag 拖动 → 更新终点（起点保持）→ 高亮实时重绘
      -- GTNH 无 setClipboard API → 复制目标为 state.clipboard（进程内
      -- 剪贴板，Ctrl+V 粘贴优先），跨游戏剪贴板不可行。
      local tx, ty = char, code
      if type(tx) == "number" and type(ty) == "number" then
        local inputY = state.height - (state.scrollSafe and 1 or 0)
        if ty == inputY then
          -- 输入行: 按列换算字符索引（第 1 列是边框，prompt 从 4/5 列起）
          local line_start = lastLineStart(state.inputBuffer)
          local multiline = line_start > 0
          local inputStart = multiline and 5 or 4
          local rel = tx - inputStart
          if rel < 0 then rel = 0 end
          -- 遍历显示文本找 rel 列对应字符索引（逐字符累积显示宽度）
          local displayText = multiline and usub(state.inputBuffer, line_start + 1)
            or state.inputBuffer
          local idx = 0
          local w = 0
          while idx < ulen(displayText) do
            local ch = usub(displayText, idx + 1, idx + 1)
            local cw = ulen(ch) == 2 and 2 or 1
            if w + cw > rel then break end
            w = w + cw
            idx = idx + 1
          end
          local charIdx = line_start + idx
          if ev == "touch" then
            -- 按下: 起点 = 终点 = 点击位（清除旧选中）
            state.sel = {a = charIdx, b = charIdx}
            state.sel_active = true
          elseif state.sel and state.sel_active then
            -- 拖动: 更新终点（起点保持）——不移动光标
            state.sel.b = charIdx
          end
          state.inputCursor = charIdx
          state.completionCycle = nil
          pcall(tui.drawInput)
        elseif ev == "drag" and state.sel and state.sel_active then
          -- 拖出输入行: 终点 = 行首/行尾（向拖动方向延伸）
          local line_start = lastLineStart(state.inputBuffer)
          local len = ulen(state.inputBuffer)
          state.sel.b = ty < inputY and line_start or len
          pcall(tui.drawInput)
        end
      end
    elseif ev == "scroll" then
      -- 鼠标滚轮: char == 1 上滚 3 行, -1 下滚 3 行（oc-ai 同）
      if char == 1 then
        tui.scrollUp(3)
      elseif char == -1 then
        tui.scrollDown(3)
      end
    end
  end
end

function tui.isRunning()
  return state.running
end

function tui.stop()
  state.running = false
end

-- 清空会话显示
function tui.clear()
  state.history = {}
  state.scrollOffset = 0
  pcall(function()
    term.clear()
    tui.drawHeader()
    tui.drawStatus()
    tui.drawInput()
  end)
end

-- 退出恢复终端
function tui.cleanup()
  pcall(function()
    term.clear()
    local g = component.gpu
    g.setBackground(0x000000)
    g.setForeground(0xffffff)
  end)
end

-- 测试/调试只读: 内容区消息列表 {text, color}
function tui.history()
  return state.history
end

-- 进入 TUI 时显示会话历史（填充内容区，避免空屏/下半空白）:
-- 最近优先，最多 30 条；跳过 folded 折叠段与空内容；
-- 摘要消息（[对话摘要] system）以 dim 色显示。按旧→新顺序打印。
-- 当前不截断：完整显示（内容区可滚动查看全文）。
function tui.printHistory(messages)
  if type(messages) ~= "table" then return end
  local collected = {}
  for i = #messages, 1, -1 do
    if #collected >= 30 then break end
    local m = messages[i]
    if m and not m.folded then
      if m.role == "user" then
        local c = tostring(m.content or "")
        if c ~= "" then collected[#collected + 1] = {role = "user", text = c} end
      elseif m.role == "assistant" and m.content then
        local c = tostring(m.content)
        if c ~= "" then collected[#collected + 1] = {role = "assistant", text = c} end
      elseif m.role == "system" and type(m.content) == "string"
          and m.content:match("^%[对话摘要%]") then
        collected[#collected + 1] = {role = "system", text = m.content}
      end
    end
  end
  for i = #collected, 1, -1 do
    local e = collected[i]
    if e.role == "user" then
      tui.printRole("user", e.text)
    elseif e.role == "assistant" then
      tui.printRole("assistant", e.text)
    else
      tui.print(e.text, tui.colors.dim)
    end
  end
end

-- 测试钩子: 直接设置输入 buffer（模拟粘贴结果）——ocvm 上事件循环模拟
-- 不可靠（协程 event.pull 卡死），真机验证渲染路径用此钩子。
function tui.debug_set_buffer(s)
  state.inputBuffer = tostring(s or "")
  state.inputCursor = ulen(state.inputBuffer)
end

return tui
end

-- agent.agent.tools.file (embedded module)
package.preload["agent.tools.file"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.tools.file — file tools: read_file / edit_file / append_file
-- / write_file / list_directory / search_files / glob.
--
-- search_files and glob are ported from oc-ai lib/cmn-utils/grep.lua
-- and glob.lua (recursive directory search + line numbers + literal/
-- Lua pattern + glob filter + max results/line length caps).
--
-- Module contract: exports {tools = {...}, exec = function(name, args,
-- deps)}. exec returns nil for tool names it does not handle. deps is
-- injected per call by agent.execute (via agent.lua's execute_tool).
-- ═══════════════════════════════════════════════════════════════

local tools = {
  {type="function", ["function"]={
    name="read_file",
    description="Read file contents. Optional offset (1-based line number) and limit (max lines) read a slice of a large file instead of the whole thing; negative offset counts from the end (tail). When offset is given, lines are prefixed with their number. Omit both to read the whole file.",
    parameters={type="object", properties={path={type="string", description="File path"}, offset={type="number", description="Start line (1-based); negative = from end (e.g. -5 = last 5 lines)"}, limit={type="number", description="Max lines to read (after offset)"}}, required={"path"}}
  }},
  {type="function", ["function"]={
    name="edit_file",
    description="Edit a file by replacing an exact string match. The old_string must be unique unless replace_all is true. Use read_file first to see the exact text. For large files or appending, prefer append_file. Rejects files over 20KB.",
    parameters={type="object", properties={path={type="string", description="File path"}, old_string={type="string", description="Exact text to find (must be unique unless replace_all)"}, new_string={type="string", description="Replacement text"}, replace_all={type="boolean", description="Replace all occurrences (default false)"}}, required={"path", "old_string", "new_string"}}
  }},
  {type="function", ["function"]={
    name="append_file",
    description="Append content to the end of a file (creates it if missing). O(1) memory regardless of file size — use for logs, growing records, or adding to large files without reading them first.",
    parameters={type="object", properties={path={type="string", description="File path"}, content={type="string", description="Content to append"}}, required={"path", "content"}}
  }},
  {type="function", ["function"]={
    name="write_file",
    description="Write content to a file",
    parameters={type="object", properties={path={type="string", description="File path"}, content={type="string", description="Content to write"}}, required={"path", "content"}}
  }},
  {type="function", ["function"]={
    name="list_directory",
    description="List files in a directory",
    parameters={type="object", properties={path={type="string", description="Directory path"}}, required={"path"}}
  }},
  {type="function", ["function"]={
    name="search_files",
    description="Search file contents for a pattern, returning matching lines as 'path:line: content' (one per line). Recurses directories. pattern is a Lua pattern by default; set literal=true to match a literal string. path is the file or directory to search (default: current directory). glob restricts which files are searched (e.g. '*.lua'). max_results caps the number of matches (default 50); max_line_length truncates long lines (default 200).",
    parameters={type="object", properties={
      pattern={type="string", description="Pattern to search for (Lua pattern unless literal=true)"},
      path={type="string", description="File or directory to search (default: current directory)"},
      glob={type="string", description="Only search files matching this glob pattern (e.g. '*.lua')"},
      literal={type="boolean", description="Treat pattern as a literal string (default false)"},
      max_results={type="number", description="Maximum number of results (default 50)"},
      max_line_length={type="number", description="Maximum line length to return (default 200)"}
    }, required={"pattern"}}
  }},
  {type="function", ["function"]={
    name="glob",
    description="Find files matching a glob pattern, recursively. Returns matching paths relative to path (one per line). Supports '*' (within a path segment) and '**' (across segments), e.g. '*.lua' or 'lib/**/*.lua'. path is the starting directory (default: current directory).",
    parameters={type="object", properties={
      pattern={type="string", description="Glob pattern to match (e.g. '*.lua', 'lib/**/*.lua')"},
      path={type="string", description="Starting directory (default: current directory)"}
    }, required={"pattern"}}
  }},
}

-- ═══════════════════════════════════════════════════════════════
-- search_files / glob — grep/glob file search (ported from oc-ai
-- lib/cmn-utils/grep.lua and lib/cmn-utils/glob.lua).
--
-- Path handling is deliberately portable: io.open works in every
-- environment (real OpenOS, host mock, tests), so it is the primary
-- file/dir discriminator; fs.isDirectory / fs.list are used as
-- fallbacks for hosts whose isDirectory is unreliable (e.g. oc_mock
-- returns false always). fs.concat/fs.name are not used because the
-- mock lacks them — plain string ops instead.
-- ═══════════════════════════════════════════════════════════════

-- Escape Lua pattern magic characters for literal search
local function escape_literal(str)
  return (str:gsub("([%^%$%(%)%%%.%[%]%*%+%-%?])", "%%%1"))
end

-- UTF-8 安全截断: 取前 n 字节，回退到字符边界（不劈裂多字节字符）。
-- 续字节 = 0x80-0xBF；单字节 < 0x80；起始字节 0xC0+。
local function utf8_cut(s, n)
  if not s or #s <= n then return s end
  local cut = n
  while cut < #s and cut >= 1 do
    local b = s:byte(cut + 1)
    if not b or b < 0x80 or b >= 0xC0 then break end
    cut = cut - 1
  end
  if cut < 0 then cut = 0 end
  return s:sub(1, cut)
end

-- Convert a glob pattern to a Lua pattern. Supports '*' (within a
-- path segment) and '**' (across segments): e.g. '*.lua', 'lib/**/*.lua'.
local function glob_to_lua_pattern(glob_pat)
  local pat = glob_pat
  pat = (pat:gsub("([%^%$%(%)%%%.%[%]%+%-%?])", "%%%1"))
  pat = (pat:gsub("%*%*", "\001"))
  pat = (pat:gsub("%*", "[^/]*"))
  pat = (pat:gsub("\001", ".*"))
  return "^" .. pat .. "$"
end

-- Simple name glob match ('*' = anything), used for the search_files
-- glob filter on file names (e.g. '*.lua'). Returns true when no
-- filter is given.
local function glob_match(name, pattern)
  if not pattern then return true end
  local pat = pattern
  pat = (pat:gsub("([%^%$%(%)%%%.%[%]%+%-%?])", "%%%1"))
  pat = (pat:gsub("%*", ".*"))
  return name:match("^" .. pat .. "$") ~= nil
end

-- Last path component (portable fs.name)
local function path_name(p)
  local name = p:match("([^/\\]+)[/\\]*$")
  return name or p
end

-- Classify a path: "file", "dir" or "missing". io.open first (works
-- everywhere — opening a directory fails), then fs.isDirectory, then
-- fs.list (for hosts whose isDirectory always returns false).
local function classify_path(path, fs)
  local f = io.open(path, "r")
  if f then
    f:close()
    return "file"
  end
  if fs and fs.isDirectory then
    local ok, r = pcall(fs.isDirectory, path)
    if ok and r then return "dir" end
  end
  if fs and fs.list then
    local ok, it = pcall(fs.list, path)
    if ok and type(it) == "function" then
      if it() then return "dir" end
    end
  end
  return "missing"
end

-- search_files: recursive content search.
-- args: pattern, path, glob, literal, max_results, max_line_length.
-- Returns one 'path:line: content' line per match.
local function search_files_code(args)
  local ok_fs, fs = pcall(require, "filesystem")
  local pattern = args.pattern
  if type(pattern) ~= "string" or pattern == "" then
    error("pattern must be a non-empty string")
  end
  local base = (args.path ~= nil and args.path ~= "") and args.path or "."
  local max_results = tonumber(args.max_results) or 50
  local max_line_length = tonumber(args.max_line_length) or 200
  local glob_filter = args.glob

  local pat = pattern
  if args.literal then
    pat = escape_literal(pat)
  end

  local results = {}
  local truncated = false

  -- Search one file; returns true when the result cap is reached.
  local function search_file(full_path, rel_path)
    local f = io.open(full_path, "r")
    if not f then return false end
    local line_num = 0
    for line in f:lines() do
      line_num = line_num + 1
      local ok_find, found = pcall(line.find, line, pat)
      if ok_find and found then
        local shown = line
        -- 超长行: UTF-8 安全截断 + 显式标记（pi 风格，不静默丢内容）
        if #shown > max_line_length then
          shown = utf8_cut(shown, max_line_length)
            .. " ... [line truncated at " .. max_line_length .. "]"
        end
        results[#results + 1] = rel_path .. ":" .. line_num .. ": " .. shown
        if #results >= max_results then
          truncated = true
          f:close()
          return true
        end
      end
    end
    f:close()
    return false
  end

  local stopped = false
  local function walk(dir, prefix)
    if stopped then return end
    local kind = classify_path(dir, fs)
    if kind == "file" then
      -- Single-file target: glob filter applies to the file name
      if glob_match(path_name(dir), glob_filter) then
        if search_file(dir, prefix) then stopped = true end
      end
      return
    end
    if kind ~= "dir" then return end
    local ok_list, it = pcall(function() return fs.list(dir) end)
    if not ok_list or type(it) ~= "function" then return end
    for entry in it do
      if stopped then return end
      local full = dir .. "/" .. entry
      local rel = prefix == "" and entry or (prefix .. "/" .. entry)
      local sub = classify_path(full, fs)
      if sub == "dir" then
        walk(full, rel)
      elseif sub == "file" then
        if glob_match(entry, glob_filter) then
          if search_file(full, rel) then
            stopped = true
            return
          end
        end
      end
    end
  end

  local base_kind = classify_path(base, fs)
  local prefix = base_kind == "file" and path_name(base) or ""
  walk(base, prefix)

  if #results == 0 then
    return "No matches for '" .. tostring(args.pattern) .. "' in " .. base
  end
  local out = {("Match " .. #results .. " for '" .. tostring(args.pattern)
    .. "' in " .. base .. ":")}
  for i = 1, #results do
    out[#out + 1] = results[i]
  end
  if truncated then
    out[#out + 1] = "(results truncated at " .. max_results .. ")"
  end
  return table.concat(out, "\n")
end

-- glob: recursive glob pattern match over relative paths.
-- args: pattern, path.
local function glob_code(args)
  local ok_fs, fs = pcall(require, "filesystem")
  local pattern = args.pattern
  if type(pattern) ~= "string" or pattern == "" then
    error("pattern must be a non-empty string")
  end
  local base = (args.path ~= nil and args.path ~= "") and args.path or "."
  local lua_pat = glob_to_lua_pattern(pattern)
  local matches = {}

  local function walk(dir, prefix)
    if classify_path(dir, fs) ~= "dir" then return end
    local ok_list, it = pcall(function() return fs.list(dir) end)
    if not ok_list or type(it) ~= "function" then return end
    for entry in it do
      local full = dir .. "/" .. entry
      local rel = prefix == "" and entry or (prefix .. "/" .. entry)
      if classify_path(full, fs) == "dir" then
        walk(full, rel)
      else
        if rel:match(lua_pat) then
          matches[#matches + 1] = rel
        end
      end
    end
  end

  walk(base, "")
  table.sort(matches)
  if #matches == 0 then
    return "No files match '" .. tostring(args.pattern) .. "' in " .. base
  end
  return table.concat(matches, "\n")
end

local function exec(name, args, deps)
  if name == "read_file" then
    local ok, result = pcall(function()
      local f = io.open(args.path, "r")
      if not f then error("file not found: " .. args.path) end
      local offset = args.offset
      local limit = args.limit
      -- 无 offset/limit 的默认读: 有行/字节上限，避免大文件全量回传。
      -- 上限与 edit_file 的 20KB 预算一致; 超限时尾注给出续读指引。
      local READ_MAX_LINES = 400
      local READ_MAX_BYTES = 20000
      if offset == nil and limit == nil then
        local parts = {}
        local n = 0
        local total_bytes = 0
        for line in f:lines() do
          n = n + 1
          total_bytes = total_bytes + #line + 1
          if n > READ_MAX_LINES or total_bytes > READ_MAX_BYTES then
            f:close()
            -- 截断: 返回已收集的行 + 尾注（提示用 offset 续读）
            local out = table.concat(parts, "\n")
            local shown = #parts
            return out .. "\n...(truncated: showing first " .. shown
              .. " lines; use read_file with offset=" .. (shown + 1)
              .. " to continue)"
          end
          parts[#parts + 1] = line
        end
        f:close()
        return table.concat(parts, "\n")
      end
      -- Line-slice mode: count lines first (needed for negative offset / tail)
      local total = 0
      for _ in f:lines() do total = total + 1 end
      f:close()
      local start = offset or 1
      if start < 0 then start = total + start + 1 end  -- e.g. -5 -> total-4
      if start < 1 then start = 1 end
      -- Re-open and collect the slice (O(target lines) memory)
      local f2 = io.open(args.path, "r")
      if not f2 then error("cannot reopen: " .. args.path) end
      local parts = {}
      local n = 0
      local collected = 0
      for line in f2:lines() do
        n = n + 1
        if n >= start then
          collected = collected + 1
          parts[#parts + 1] = n .. ". " .. line
          if limit and collected >= limit then break end
        end
      end
      f2:close()
      if #parts == 0 then
        return "no lines (file has " .. total .. " lines; offset " .. tostring(offset or 1) .. ")"
      end
      local out = table.concat(parts, "\n")
      -- 切片结果仍超上限（limit 参数过大）: 同样尾注
      if #out > READ_MAX_BYTES then
        out = out:sub(1, READ_MAX_BYTES)
          .. "\n...(truncated: slice output exceeds " .. READ_MAX_BYTES
          .. " bytes; use read_file with a smaller limit to continue)"
      end
      return out
    end)
    return ok and result or ("Error: " .. tostring(result))

  elseif name == "edit_file" then
    local ok, result = pcall(function()
      local f = io.open(args.path, "r")
      if not f then error("file not found: " .. args.path) end
      local content = f:read("*a")
      f:close()
      if #content > 20000 then
        error("file too large for edit_file (" .. #content .. " bytes, max 20000). Use read_file with offset/limit + append_file.")
      end
      local old = args.old_string
      if old == nil or old == "" then error("old_string must be non-empty") end
      local new = args.new_string or ""
      -- Count occurrences (plain text, no patterns)
      local count = 0
      local pos = 1
      while true do
        local found = content:find(old, pos, true)
        if not found then break end
        count = count + 1
        pos = found + 1
      end
      if count == 0 then
        error("old_string not found in file")
      end
      if count > 1 and not args.replace_all then
        error("old_string found " .. count .. " times; use replace_all=true or a longer unique match")
      end
      local newContent
      if args.replace_all then
        -- literal replace-all: escape magic chars in pattern and % in replacement.
        -- NOTE: wrap inner gsub calls in parens — gsub returns (result, count),
        -- and a bare call as an argument would expand both values.
        local pat = (old:gsub("([%^%$%(%)%%%.%[%]%*%+%-%?])", "%%%1"))
        local repl = (new:gsub("%%", "%%%%"))
        newContent = content:gsub(pat, repl)
      else
        local idx = content:find(old, 1, true)
        newContent = content:sub(1, idx - 1) .. new .. content:sub(idx + #old)
      end
      local fw = io.open(args.path, "w")
      if not fw then error("cannot write: " .. args.path) end
      fw:write(newContent)
      fw:close()
      return "Replaced " .. (args.replace_all and count or 1) .. " occurrence(s) in " .. args.path
    end)
    return ok and result or ("Error: " .. tostring(result))

  elseif name == "append_file" then
    local ok, result = pcall(function()
      local f = io.open(args.path, "a")
      if not f then error("cannot open for append: " .. args.path) end
      f:write(args.content or "")
      f:close()
      return "Appended " .. (#(args.content or "") ) .. " bytes to " .. args.path
    end)
    return ok and result or ("Error: " .. tostring(result))

  elseif name == "write_file" then
    local ok, result = pcall(function()
      local f = io.open(args.path, "w")
      if not f then error("cannot open for writing: " .. args.path) end
      f:write(args.content)
      f:close()
      return "Written to " .. args.path
    end)
    return ok and result or ("Error: " .. tostring(result))

  elseif name == "list_directory" then
    local ok, result = pcall(function()
      local fs = require("filesystem")
      local parts = {}
      for f in fs.list(args.path or "/") do
        parts[#parts + 1] = f
      end
      if #parts == 0 then return "(empty)" end
      return table.concat(parts, "\n")
    end)
    return ok and result or ("Error: " .. tostring(result))

  elseif name == "search_files" then
    local ok, result = pcall(search_files_code, args)
    return ok and result or ("Error: " .. tostring(result))

  elseif name == "glob" then
    local ok, result = pcall(glob_code, args)
    return ok and result or ("Error: " .. tostring(result))
  end

  return nil  -- not handled by this module
end

return {tools = tools, exec = exec}
end

-- agent.agent.tools.data (embedded module)
package.preload["agent.tools.data"] = function()
-- ═══════════════════════════════════════════════════════════════
-- agent.tools.data — data tools: json_query / calc / text_ops.
--
-- Module contract: exports {tools = {...}, exec = function(name, args,
-- deps)}. exec returns nil for tool names it does not handle. deps is
-- injected per call by agent.execute; json comes from deps.json (the
-- same global table agent.lua defines in Phase 1 — never referenced
-- as a global here, so Phase 2 can swap in a json module).
-- ═══════════════════════════════════════════════════════════════

local tools = {
  {type="function", ["function"]={
    name="json_query",
    description="Extract a value from a JSON string using a dot path (e.g. 'hits.0.title', 'data.items.3.name'). Arrays are indexed from 0. Returns the matched value (JSON for objects/arrays, plain text for scalars). Use to parse component_invoke, web_search or file contents.",
    parameters={type="object", properties={json={type="string", description="JSON text to query"}, path={type="string", description="Dot-separated path, e.g. 'hits.0.title'"}}, required={"json", "path"}}
  }},
  {type="function", ["function"]={
    name="calc",
    description="Evaluate a safe arithmetic expression. Supports + - * / % ^, parentheses, and functions: sqrt, abs, floor, ceil, min, max. Does NOT execute code — use for math only. Example: 'sqrt(2)*10^3'",
    parameters={type="object", properties={expression={type="string", description="Arithmetic expression to evaluate"}}, required={"expression"}}
  }},
  {type="function", ["function"]={
    name="text_ops",
    description="String manipulation operations: find(text, pattern) -> position or nil; replace(text, old, new) -> new text; split(text, sep) -> numbered lines; slice(text, start, length); upper(text); lower(text); trim(text); length(text).",
    parameters={type="object", properties={op={type="string", description="Operation: find, replace, split, slice, upper, lower, trim, length"}, text={type="string", description="Input text"}, arg1={type="string", description="First argument (pattern/old/separator/start)"}, arg2={type="string", description="Second argument (new/length)"}}, required={"op", "text"}}
  }},
}

-- json_query: extract value from JSON via dot path (arrays 0-indexed)
local function json_query_code(json, json_str, path)
  if type(json_str) ~= "string" then return "Error: json argument must be a string" end
  local ok_decode, data = pcall(json.decode, json_str)
  if not ok_decode then
    return "Error: invalid JSON: " .. tostring(data)
  end

  local cur = data
  if path == nil or path == "" then
    -- no path: return whole value
    if type(cur) == "table" then return json.encode(cur) end
    if type(cur) == "boolean" then return tostring(cur) end
    return tostring(cur or "null")
  end

  for seg in (path .. "."):gmatch("([^%.]+)%.") do
    if type(cur) ~= "table" then
      return "Error: cannot descend into " .. type(cur) .. " at '" .. seg .. "'"
    end
    local idx = tonumber(seg)
    local next_val
    if idx ~= nil then
      next_val = cur[idx + 1]  -- JSON array index → 1-based Lua table
    else
      next_val = cur[seg]
    end
    if next_val == nil then
      return "Error: path not found at '" .. seg .. "'"
    end
    cur = next_val
  end

  if type(cur) == "table" then return json.encode(cur) end
  if type(cur) == "boolean" then return tostring(cur) end
  return tostring(cur or "null")
end

-- calc: safe arithmetic expression evaluator (no code execution)
local function calc_code(expr)
  if type(expr) ~= "string" or expr == "" then
    return "Error: expression must be a non-empty string"
  end

  local pos = 1
  local function peek()
    while expr:sub(pos, pos):match("%s") do pos = pos + 1 end
    return expr:sub(pos, pos)
  end

  local function parse_primary()
    peek()
    local c = expr:sub(pos, pos)
    if c == "(" then
      pos = pos + 1
      local v = parse_expr()
      peek()
      if expr:sub(pos, pos) ~= ")" then error("expected ')'") end
      pos = pos + 1
      return v
    end
    -- function call: name(...)
    local name = expr:match("^([a-zA-Z_][a-zA-Z0-9_]*)%s*%(", pos)
    if name then
      pos = pos + #name
      peek()
      if expr:sub(pos, pos) ~= "(" then error("expected '(' after " .. name) end
      pos = pos + 1
      local args = {}
      peek()
      if expr:sub(pos, pos) ~= ")" then
        while true do
          args[#args + 1] = parse_expr()
          peek()
          local cc = expr:sub(pos, pos)
          if cc == "," then pos = pos + 1
          elseif cc == ")" then break
          else error("expected ',' or ')'") end
        end
      end
      pos = pos + 1
      local fns = {
        sqrt = function(x) return math.sqrt(x) end,
        abs = function(x) return math.abs(x) end,
        floor = function(x) return math.floor(x) end,
        ceil = function(x) return math.ceil(x) end,
        min = function(...) return math.min(...) end,
        max = function(...) return math.max(...) end,
      }
      if not fns[name] then error("unknown function: " .. name) end
      return fns[name](table.unpack(args))
    end
    local rest = expr:sub(pos)
    -- strict number: optional sign, digits, optional fraction; exponent handled
    -- separately (a capture group would return nil when the exponent is absent)
    local num = rest:match("^%-?%d+%.?%d*")
    if not num or num == "" then error("expected number at " .. pos) end
    local exp = rest:sub(#num + 1):match("^[eE][%-+]?%d+")
    if exp then num = num .. exp end
    pos = pos + #num
    return tonumber(num)
  end

  local function parse_unary()
    peek()
    if expr:sub(pos, pos) == "-" then
      pos = pos + 1
      return -parse_unary()
    end
    if expr:sub(pos, pos) == "+" then
      pos = pos + 1
      return parse_unary()
    end
    return parse_primary()
  end

  local function parse_power()
    local v = parse_unary()
    peek()
    if expr:sub(pos, pos) == "^" then
      pos = pos + 1
      return v ^ parse_power()
    end
    return v
  end

  local function parse_mul()
    local v = parse_power()
    while true do
      peek()
      local c = expr:sub(pos, pos)
      if c == "*" then pos = pos + 1; v = v * parse_power()
      elseif c == "/" then pos = pos + 1; v = v / parse_power()
      elseif c == "%" then pos = pos + 1; v = v % parse_power()
      else return v end
    end
  end

  local function parse_add()
    local v = parse_mul()
    while true do
      peek()
      local c = expr:sub(pos, pos)
      if c == "+" then pos = pos + 1; v = v + parse_mul()
